INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(70603, 2223, 327, '<td valign="top">This is nice, well done. Goooood work.</td>', 'This is nice, well done. Goooood work.', '2002-06-10 18:43:00.000000', NULL, 1),
(70604, 2223, 1585, '<td valign="top">I truely believe that street lights are a big part of "On the road", just think of how bad things would be without "red" and "green" lights. Top five.</td>', 'I truely believe that street lights are a big part of "On the road", just think of how bad things would be without "red" and "green" lights. Top five.', '2002-06-11 01:59:00.000000', NULL, 1),
(70605, 2223, 2094, '<td valign="top">I might have framed a bit higher to try to get some of the ground clutter out of the picture, but this is nice. I like the other light in the background, it gives the eye something else to explore at once it''s finished with the foreground subject.</td>', 'I might have framed a bit higher to try to get some of the ground clutter out of the picture, but this is nice. I like the other light in the background, it gives the eye something else to explore at once it''s finished with the foreground subject.', '2002-06-11 12:20:00.000000', NULL, 1),
(70606, 2223, 89, '<td valign="top">Story of my life, great shot!</td>', 'Story of my life, great shot!', '2002-06-11 16:06:00.000000', NULL, 1),
(70607, 2223, 878, '<td valign="top">Great lighting and feel in this shot.  There is a little noticable jpg compression but nothing that would take away from my high rating of this photo.</td>', 'Great lighting and feel in this shot.  There is a little noticable jpg compression but nothing that would take away from my high rating of this photo.', '2002-06-11 17:39:00.000000', NULL, 1),
(70608, 2223, 1944, '<td valign="top">Nicely executed twilight (dawn?) shot. I especially like the care with which you showed some detail in the midground.</td>', 'Nicely executed twilight (dawn?) shot. I especially like the care with which you showed some detail in the midground.', '2002-06-11 21:52:00.000000', NULL, 1),
(70609, 2223, 772, '<td valign="top">Nice capture!  The sunset always adds a nice backdrop to most subjects :)</td>', 'Nice capture!  The sunset always adds a nice backdrop to most subjects :)', '2002-06-12 17:59:00.000000', NULL, 1),
(70610, 2223, 472, '<td valign="top">lighting is good. as is the curve form of the railing.  subject matter doesnt really grab me, but still not too shabby.</td>', 'lighting is good. as is the curve form of the railing.  subject matter doesnt really grab me, but still not too shabby.', '2002-06-12 18:18:00.000000', NULL, 1),
(70611, 2223, 1054, '<td valign="top">I like the use of negative space, but wish the light in the background could have been cropped out-of-frame somehow.</td>', 'I like the use of negative space, but wish the light in the background could have been cropped out-of-frame somehow.', '2002-06-12 21:50:00.000000', NULL, 1),
(70612, 2223, 1446, '<td valign="top">I just wish that lightpole wasn''t centered up the middle of this shot so much. I really like the lighting, colors of the sunset and the cloud formations that you captured here.</td>', 'I just wish that lightpole wasn''t centered up the middle of this shot so much. I really like the lighting, colors of the sunset and the cloud formations that you captured here.', '2002-06-13 12:09:00.000000', NULL, 1),
(70613, 2223, 1455, '<td valign="top">I like the macro shot of the green light better, more creative.</td>', 'I like the macro shot of the green light better, more creative.', '2002-06-14 00:16:00.000000', NULL, 1),
(70614, 2223, 1037, '<td valign="top">Very bold composition, and a nice sunset. It seems a bit dim and murky to me though. I''d like to see it with some higher contrast, a bit of level tweaking perhaps.</td>', 'Very bold composition, and a nice sunset. It seems a bit dim and murky to me though. I''d like to see it with some higher contrast, a bit of level tweaking perhaps.', '2002-06-14 06:04:00.000000', NULL, 1),
(70615, 2223, 2047, '<td valign="top">out of focus</td>', 'out of focus', '2002-06-15 00:07:00.000000', NULL, 1),
(70616, 2223, 332, '<td valign="top">Looks icelandic?</td>', 'Looks icelandic?', '2002-06-15 22:41:00.000000', NULL, 1),
(70617, 2223, 2000, '<td valign="top">I like the sunset contrasting the traffic lite.</td>', 'I like the sunset contrasting the traffic lite.', '2002-06-16 23:09:00.000000', NULL, 1),
(70618, 2223, 1, '<td valign="top">i think you should''ve cropped off most of the top to get less sky and more road</td>', 'i think you should''ve cropped off most of the top to get less sky and more road', '2002-06-17 00:30:00.000000', NULL, 1),
(70619, 2224, 1829, '<td valign="top">I like the combination of this photo.  Especially the as the title explains - Red, front and back.  Good job :-)</td>', 'I like the combination of this photo.  Especially the as the title explains - Red, front and back.  Good job :-)', '2002-06-10 04:04:00.000000', NULL, 1),
