(70793, 2235, 573, '<td valign="top">Is this a Rodeo thing that when you''ve been throwen you land ''On the Road''?  Wow!  every one is up in the air over this entry.</td>', 'Is this a Rodeo thing that when you''ve been throwen you land ''On the Road''?  Wow!  every one is up in the air over this entry.', '2002-06-11 14:28:00.000000', NULL, 1),
(70794, 2235, 1005, '<td valign="top">Really nice action shot, but I feel you missed the challenge concept, in my opinion.  Photo 10 Creativity (pass) Road 2 (should have passed) total 5</td>', 'Really nice action shot, but I feel you missed the challenge concept, in my opinion.  Photo 10 Creativity (pass) Road 2 (should have passed) total 5', '2002-06-11 21:01:00.000000', NULL, 1),
(70795, 2235, 1877, '<td valign="top">Wheres the road part of it all?</td>', 'Wheres the road part of it all?', '2002-06-12 02:40:00.000000', NULL, 1),
(70796, 2235, 885, '<td valign="top">Weird there are too rodeo pictures?</td>', 'Weird there are too rodeo pictures?', '2002-06-12 10:16:00.000000', NULL, 1),
(70797, 2235, 1658, '<td valign="top">I don''t really see the topic addressed here except in the name of the picture only.</td>', 'I don''t really see the topic addressed here except in the name of the picture only.', '2002-06-12 12:05:00.000000', NULL, 1),
(70798, 2235, 1054, '<td valign="top">Sorry, I don''t think this fits the challenge.</td>', 'Sorry, I don''t think this fits the challenge.', '2002-06-12 19:02:00.000000', NULL, 1),
(70799, 2235, 806, '<td valign="top">Excellent photograph.</td>', 'Excellent photograph.', '2002-06-13 08:48:00.000000', NULL, 1),
(70800, 2235, 1446, '<td valign="top">Your title is the only thing that brings this into the challenge.  But I am going to assume you really believed it met the challenge here.  Nice action shot, changing the dof to eliminate the importance of the crowd might have brought the focus to your subject a little better.</td>', 'Your title is the only thing that brings this into the challenge.  But I am going to assume you really believed it met the challenge here.  Nice action shot, changing the dof to eliminate the importance of the crowd might have brought the focus to your subject a little better.', '2002-06-13 12:03:00.000000', NULL, 1),
(70801, 2235, 1041, '<td valign="top">Great action shot.  Caught in just the right moment.  Would''ve done well for stop action, too.  I see how you are tying this to the road, but in my mind that''s a very loose connection.  Some post-process sharpening would''ve done this picture good.</td>', 'Great action shot.  Caught in just the right moment.  Would''ve done well for stop action, too.  I see how you are tying this to the road, but in my mind that''s a very loose connection.  Some post-process sharpening would''ve done this picture good.', '2002-06-14 13:12:00.000000', NULL, 1),
(70802, 2235, 2047, '<td valign="top">road...not rodio!</td>', 'road...not rodio!', '2002-06-15 00:05:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(70803, 2235, 1, '<td valign="top">Not exactly a road.</td>', 'Not exactly a road.', '2002-06-16 13:03:00.000000', NULL, 1),
(70804, 2235, 1944, '<td valign="top">My purpose with this admittidly obscure photo was a visual pun. I happened to be at the rodeo last Sunday, and when I saw what the challange was when I got back, it just kinna took hold of me. They say art is communication, and in that I''ve failed but I had fun doing it. We''ll see what happens this week.</td>', 'My purpose with this admittidly obscure photo was a visual pun. I happened to be at the rodeo last Sunday, and when I saw what the challange was when I got back, it just kinna took hold of me. They say art is communication, and in that I''ve failed but I had fun doing it. We''ll see what happens this week.', '2002-06-17 02:06:00.000000', NULL, 0),
(70805, 2235, 1897, '<td valign="top">Dude, you got ripped off!  This is totally something someone would see that was "On the Road".  And  Basson, it is rodeo not rodio.  This was a great photo that fit the challenge.  sorry these simple minds did not see it.</td>', 'Dude, you got ripped off!  This is totally something someone would see that was "On the Road".  And  Basson, it is rodeo not rodio.  This was a great photo that fit the challenge.  sorry these simple minds did not see it.', '2002-06-17 02:55:00.000000', NULL, 0),
(70806, 2235, 1944, '<td valign="top">Thanks Zeissman, I appreciate that. It was getting a litle frustrating. This week it''s gonna be better though I think.</td>', 'Thanks Zeissman, I appreciate that. It was getting a litle frustrating. This week it''s gonna be better though I think.', '2002-06-17 14:42:00.000000', NULL, 0),
(70807, 2235, 1569, '<td valign="top">I thought this pix was great---I gave it a 10!!!!!</td>', 'I thought this pix was great---I gave it a 10!!!!!', '2002-06-17 21:51:00.000000', NULL, 0),
(70808, 2236, 205, '<td valign="top">I do this so much in my car</td>', 'I do this so much in my car', '2002-06-10 06:10:00.000000', NULL, 1),
(70809, 2236, 1856, '<td valign="top">unique</td>', 'unique', '2002-06-10 13:13:00.000000', NULL, 1),
(70810, 2236, 1569, '<td valign="top">Really jumps out at you!!!!!</td>', 'Really jumps out at you!!!!!', '2002-06-10 13:32:00.000000', NULL, 1),
(70811, 2236, 885, '<td valign="top">It looks more like that spray string stuff they have at parades than alien lights to me...</td>', 'It looks more like that spray string stuff they have at parades than alien lights to me...', '2002-06-10 15:49:00.000000', NULL, 1),
(70812, 2236, 327, '<td valign="top">Fun lights, interesting. Cool</td>', 'Fun lights, interesting. Cool', '2002-06-10 17:06:00.000000', NULL, 1),
(70813, 2236, 1024, '<td valign="top">This could have been a great photo if the camera had been on a tripod.  The camera shake is much more defined at slower shutter speeds.</td>', 'This could have been a great photo if the camera had been on a tripod.  The camera shake is much more defined at slower shutter speeds.', '2002-06-10 17:36:00.000000', NULL, 1),
(70814, 2236, 1944, '<td valign="top">Looks like I feel now after too much coffee.</td>', 'Looks like I feel now after too much coffee.', '2002-06-10 18:25:00.000000', NULL, 1),
(70815, 2236, 1005, '<td valign="top">Oh, time exposure while moving.......Really interesting squigglies, but hard to view.  This turned out much better than I would have guessed.  Still, personally, I like this stuff on steady ground and let the subjects do all the moving.  It''s easier to view.  Here an idea, try a smoother road (or some outrageously expensive land yacht) and less traffic.  Photo 6 Creativity 10 Road 8 total 8</td>', 'Oh, time exposure while moving.......Really interesting squigglies, but hard to view.  This turned out much better than I would have guessed.  Still, personally, I like this stuff on steady ground and let the subjects do all the moving.  It''s easier to view.  Here an idea, try a smoother road (or some outrageously expensive land yacht) and less traffic.  Photo 6 Creativity 10 Road 8 total 8', '2002-06-10 20:33:00.000000', NULL, 1),
(70816, 2236, 1009, '<td valign="top">This is a cool effect...</td>', 'This is a cool effect...', '2002-06-10 20:34:00.000000', NULL, 1),
(70817, 2236, 1313, '<td valign="top">Somebody forgot to focus their camera.</td>', 'Somebody forgot to focus their camera.', '2002-06-10 21:25:00.000000', NULL, 1),
(70818, 2236, 714, '<td valign="top">creativety  6  interesting  8  focus N/A framing 7= 7</td>', 'creativety  6  interesting  8  focus N/A framing 7= 7', '2002-06-11 01:44:00.000000', NULL, 1),
(70819, 2236, 573, '<td valign="top">Wow, looks like a camer rattling around on the dash board with the lens open.  I like the creative spinn on the paint with light technique.</td>', 'Wow, looks like a camer rattling around on the dash board with the lens open.  I like the creative spinn on the paint with light technique.', '2002-06-11 11:47:00.000000', NULL, 1),
(70820, 2236, 1882, '<td valign="top">this pic is freaking me out</td>', 'this pic is freaking me out', '2002-06-11 12:21:00.000000', NULL, 1),
(70821, 2236, 173, '<td valign="top">What Timothy Leary''s commute home looked like.</td>', 'What Timothy Leary''s commute home looked like.', '2002-06-11 12:37:00.000000', NULL, 1),
(70822, 2236, 89, '<td valign="top">naseous</td>', 'naseous', '2002-06-11 16:15:00.000000', NULL, 1),
(70823, 2236, 1, '<td valign="top">I was never really into these shots...  In this particular one, there''s too much black space.</td>', 'I was never really into these shots...  In this particular one, there''s too much black space.', '2002-06-12 12:16:00.000000', NULL, 1),
(70824, 2236, 2173, '<td valign="top">it make me remember something...</td>', 'it make me remember something...', '2002-06-12 15:19:00.000000', NULL, 1),
(70825, 2236, 772, '<td valign="top">The lights on this photo do give the ''abstract'' look, but other than that, I think that a shorter exposure time on this photo would have been nicer in my opinion...</td>', 'The lights on this photo do give the ''abstract'' look, but other than that, I think that a shorter exposure time on this photo would have been nicer in my opinion...', '2002-06-12 18:03:00.000000', NULL, 1),
(70826, 2236, 1054, '<td valign="top">Weird.... I''m not sure what to make of it but I keep looking at it.</td>', 'Weird.... I''m not sure what to make of it but I keep looking at it.', '2002-06-13 00:37:00.000000', NULL, 1),
(70827, 2236, 1041, '<td valign="top">I''m not sure the blur works for me here.  I guess I''m missing the purpose (other than matching the title ;)</td>', 'I''m not sure the blur works for me here.  I guess I''m missing the purpose (other than matching the title ;)', '2002-06-13 10:38:00.000000', NULL, 1),
(70828, 2236, 472, '<td valign="top">wiggle that camera!  i like this effect ok.  at least it''s not just another boring picture of some random cars. : )</td>', 'wiggle that camera!  i like this effect ok.  at least it''s not just another boring picture of some random cars. : )', '2002-06-13 11:24:00.000000', NULL, 1),
(70829, 2236, 1037, '<td valign="top">That''s a very cool effect :)</td>', 'That''s a very cool effect :)', '2002-06-14 05:33:00.000000', NULL, 1),
(70830, 2236, 2235, '<td valign="top">Good idea. I like the effects of the lights. You could have just concentrated on the vehicles. The lights on the upper right somewhat distract not enhance the photo.</td>', 'Good idea. I like the effects of the lights. You could have just concentrated on the vehicles. The lights on the upper right somewhat distract not enhance the photo.', '2002-06-16 09:23:00.000000', NULL, 1),
(70831, 2241, 139, '<td valign="top">Interesting that the wipers are going.  This looks like a snapshot to me: I''d be surprised to learn that much effort was put into this.</td>', 'Interesting that the wipers are going.  This looks like a snapshot to me: I''d be surprised to learn that much effort was put into this.', '2002-06-10 01:11:00.000000', NULL, 1),
(70832, 2241, 203, '<td valign="top">Fuzzy dice and a monster winch.  You need psychological help!  :)</td>', 'Fuzzy dice and a monster winch.  You need psychological help!  :)', '2002-06-10 15:14:00.000000', NULL, 1),
(70833, 2241, 327, '<td valign="top">Fun shot, well done, bit over exposed, but is see it''s a sunny day.</td>', 'Fun shot, well done, bit over exposed, but is see it''s a sunny day.', '2002-06-10 16:55:00.000000', NULL, 1),
(70834, 2241, 772, '<td valign="top">Fuzzy dice are the coolest :)</td>', 'Fuzzy dice are the coolest :)', '2002-06-11 00:25:00.000000', NULL, 1),
(70835, 2241, 1041, '<td valign="top">Unfortunately, you had quite a range of light and shade to deal with with this shot - as a result, the light is a little too blown out.  I also noticed that you saved your file very small, maybe if you saved it bigger, you could get it a little crisper.</td>', 'Unfortunately, you had quite a range of light and shade to deal with with this shot - as a result, the light is a little too blown out.  I also noticed that you saved your file very small, maybe if you saved it bigger, you could get it a little crisper.', '2002-06-11 10:40:00.000000', NULL, 1),
(70836, 2241, 714, '<td valign="top">creativety 1 interesting 1 focus 4 framing 7 = 3</td>', 'creativety 1 interesting 1 focus 4 framing 7 = 3', '2002-06-11 14:42:00.000000', NULL, 1),
(70837, 2241, 878, '<td valign="top">This is a tough shot to get because its so bright outside of the car.</td>', 'This is a tough shot to get because its so bright outside of the car.', '2002-06-11 17:53:00.000000', NULL, 1),
(70838, 2241, 1005, '<td valign="top">Popular concept, color is washed out/pale.  Is the road really WHITE?  Photo 5 Creativity 6 Road 7 total 6</td>', 'Popular concept, color is washed out/pale.  Is the road really WHITE?  Photo 5 Creativity 6 Road 7 total 6', '2002-06-11 20:58:00.000000', NULL, 1),
(70839, 2241, 1877, '<td valign="top">Doesn''t seem to be anything really special about this picture.  I like the dice.. maybe the dice on the road - dice eye view type thing?</td>', 'Doesn''t seem to be anything really special about this picture.  I like the dice.. maybe the dice on the road - dice eye view type thing?', '2002-06-12 02:41:00.000000', NULL, 1),
(70840, 2241, 472, '<td valign="top">not really enough going on in this pic.  also the outside is really washed out., whats with the windshield wipers on?</td>', 'not really enough going on in this pic.  also the outside is really washed out., whats with the windshield wipers on?', '2002-06-12 18:14:00.000000', NULL, 1),
(70841, 2241, 1054, '<td valign="top">This shot seems a bit overexposed.  I understand the difficulty of shooting a bright sky from a dark car; perhaps shooting at just would have helped.</td>', 'This shot seems a bit overexposed.  I understand the difficulty of shooting a bright sky from a dark car; perhaps shooting at just would have helped.', '2002-06-13 00:44:00.000000', NULL, 1),
(70842, 2241, 1, '<td valign="top">The rearview blocking out most of the road, I''d try a different angle.  Your image is really bright and washed out too -- try a higher F stop (aperture) or faster shutter speed.</td>', 'The rearview blocking out most of the road, I''d try a different angle.  Your image is really bright and washed out too -- try a higher F stop (aperture) or faster shutter speed.', '2002-06-13 09:31:00.000000', NULL, 1),
(70843, 2241, 811, '<td valign="top">A very sunny day, it looks like.  I understand that the brightness may be deliberate -- the whites almost wash out.  If the greens could have been sharper or greener, that would have been an awesome effect.</td>', 'A very sunny day, it looks like.  I understand that the brightness may be deliberate -- the whites almost wash out.  If the greens could have been sharper or greener, that would have been an awesome effect.', '2002-06-13 17:38:00.000000', NULL, 1),
(70844, 2244, 1379, '<td valign="top">Awesome sky.  Looks so foreboding. I hope you got outta there before that road turned to mud!</td>', 'Awesome sky.  Looks so foreboding. I hope you got outta there before that road turned to mud!', '2002-06-10 09:46:00.000000', NULL, 1),
(70845, 2244, 1, '<td valign="top">Nice shot, the green/brown/gray is a great color combination.</td>', 'Nice shot, the green/brown/gray is a great color combination.', '2002-06-10 10:09:00.000000', NULL, 1),
(70846, 2244, 1856, '<td valign="top">other than the tire tracks...this looks like a classic painting.  It''s beautiful.</td>', 'other than the tire tracks...this looks like a classic painting.  It''s beautiful.', '2002-06-10 13:25:00.000000', NULL, 1),
(70847, 2244, 772, '<td valign="top">Yup.. it''s a road.. Looks like it''s gonna rain also... better get yer umbrella out :)</td>', 'Yup.. it''s a road.. Looks like it''s gonna rain also... better get yer umbrella out :)', '2002-06-10 15:04:00.000000', NULL, 1),
(70848, 2244, 1944, '<td valign="top">Just the right road for this shot. Evocative.</td>', 'Just the right road for this shot. Evocative.', '2002-06-10 16:26:00.000000', NULL, 1),
(70849, 2244, 641, '<td valign="top">I personally like it more with the sky cropped out really low.. about  an inch or so above the trees.. It makes the road more dramatic to me.</td>', 'I personally like it more with the sky cropped out really low.. about  an inch or so above the trees.. It makes the road more dramatic to me.', '2002-06-10 17:07:00.000000', NULL, 1),
(70850, 2244, 1005, '<td valign="top">Appears to be a long way to anywhere.  Good scenery shot, nice landscape, clouds, but (nit time) where''s the interest/tension/reason to view.....if you had a person or a car in the deep, deep distance, or even dust clouds from a recent passage, might have introduced some mystery.  Another nit, the trees on the left are soooo dark, they appear almost black, (was this in the black forest?).  Photo 7 Creativity 6 Road 8 total 7</td>', 'Appears to be a long way to anywhere.  Good scenery shot, nice landscape, clouds, but (nit time) where''s the interest/tension/reason to view.....if you had a person or a car in the deep, deep distance, or even dust clouds from a recent passage, might have introduced some mystery.  Another nit, the trees on the left are soooo dark, they appear almost black, (was this in the black forest?).  Photo 7 Creativity 6 Road 8 total 7', '2002-06-10 17:36:00.000000', NULL, 1),
(70851, 2244, 811, '<td valign="top">Good symmetry.  It may have also been interesting to put the camera on a lower plane (like knee-level).  I know you can''t control the sky, but it would have been much more interesting if it was blue, or partly cloudy, or even if you could really see the details of the clouds.</td>', 'Good symmetry.  It may have also been interesting to put the camera on a lower plane (like knee-level).  I know you can''t control the sky, but it would have been much more interesting if it was blue, or partly cloudy, or even if you could really see the details of the clouds.', '2002-06-10 18:11:00.000000', NULL, 1),
(70852, 2244, 327, '<td valign="top">Cloudy day and long road. Nice perspective.</td>', 'Cloudy day and long road. Nice perspective.', '2002-06-10 18:16:00.000000', NULL, 1),
(70853, 2244, 554, '<td valign="top">I would have croped most of the sky</td>', 'I would have croped most of the sky', '2002-06-10 23:11:00.000000', NULL, 1),
(70854, 2244, 714, '<td valign="top">creativety  3   interesting  3  focus 9 framing 8=5</td>', 'creativety  3   interesting  3  focus 9 framing 8=5', '2002-06-11 01:25:00.000000', NULL, 1),
(70855, 2244, 1897, '<td valign="top">psuedo interesting sky, a polarizer would help.  I do not think we actually had to take pictures of a road though.</td>', 'psuedo interesting sky, a polarizer would help.  I do not think we actually had to take pictures of a road though.', '2002-06-11 02:22:00.000000', NULL, 1),
(70856, 2244, 2135, '<td valign="top">This image lacks interest and is flat.</td>', 'This image lacks interest and is flat.', '2002-06-11 22:52:00.000000', NULL, 1),
(70857, 2244, 1877, '<td valign="top">It just lacks something .. I dunno what.. I mean it totally has potential! Maybe theres just too much road at the bottom? I dunno.. or like if the sun was peeking through the clouds.. but a good spot, take more pics there during different weather?</td>', 'It just lacks something .. I dunno what.. I mean it totally has potential! Maybe theres just too much road at the bottom? I dunno.. or like if the sun was peeking through the clouds.. but a good spot, take more pics there during different weather?', '2002-06-12 02:36:00.000000', NULL, 1),
(70858, 2244, 1031, '<td valign="top">I see the vanishing point a little left, and the road edges not quite parallel. Plus 1 point if deliberate, minus 1/2 point if accidental...</td>', 'I see the vanishing point a little left, and the road edges not quite parallel. Plus 1 point if deliberate, minus 1/2 point if accidental...', '2002-06-12 03:33:00.000000', NULL, 1),
(70859, 2244, 208, '<td valign="top">I really like the simplicity and the colors of this shot: brown road, green grass/trees, grey sky.</td>', 'I really like the simplicity and the colors of this shot: brown road, green grass/trees, grey sky.', '2002-06-12 17:20:00.000000', NULL, 1),
(70860, 2244, 472, '<td valign="top">nicely shot. nothing wrong with the pic, although the subject matter is not particularly interesting</td>', 'nicely shot. nothing wrong with the pic, although the subject matter is not particularly interesting', '2002-06-12 18:21:00.000000', NULL, 1),
(70861, 2244, 1054, '<td valign="top">The colors in this shot are uninteresting, but the textures are great.  This would have made a great B/W or sepia shot.</td>', 'The colors in this shot are uninteresting, but the textures are great.  This would have made a great B/W or sepia shot.', '2002-06-12 23:57:00.000000', NULL, 1),
(70862, 2244, 1041, '<td valign="top">Not very much to look at though.  Like how the road disappears in the distance, would probably prefer less sky (ROT).</td>', 'Not very much to look at though.  Like how the road disappears in the distance, would probably prefer less sky (ROT).', '2002-06-13 15:22:00.000000', NULL, 1),
(70863, 2244, 2109, '<td valign="top">Looks like a good candidate for a book cover  Easy on the eyes, potentially tells a story of a "long road", and there''s plenty of space for title and text.</td>', 'Looks like a good candidate for a book cover  Easy on the eyes, potentially tells a story of a "long road", and there''s plenty of space for title and text.', '2002-06-13 22:39:00.000000', NULL, 1),
(70864, 2244, 89, '<td valign="top">yes. a dirt road. and clouds. good contrasts, bad subject perhaps?</td>', 'yes. a dirt road. and clouds. good contrasts, bad subject perhaps?', '2002-06-13 22:40:00.000000', NULL, 1),
(70865, 2244, 1042, '<td valign="top">I like th colors in this, looks like it''s just before a storm. I also like the perspective. Good job.</td>', 'I like th colors in this, looks like it''s just before a storm. I also like the perspective. Good job.', '2002-06-14 10:41:00.000000', NULL, 1),
(70866, 2244, 2235, '<td valign="top">Concept OK. Need some type of interest on road (person maybe). Too much sky. Mainly it loses focus of idea with not center of interest to draw eye.</td>', 'Concept OK. Need some type of interest on road (person maybe). Too much sky. Mainly it loses focus of idea with not center of interest to draw eye.', '2002-06-16 09:13:00.000000', NULL, 1),
(70867, 2244, 2176, '<td valign="top">Finally I see an Armenian interested in photography.  Its a cool picture that you have there.  We need to see more of your creativity please.  You''re ARMENIAN.  I know you have more interesting stuff to show.  HYE MNAS</td>', 'Finally I see an Armenian interested in photography.  Its a cool picture that you have there.  We need to see more of your creativity please.  You''re ARMENIAN.  I know you have more interesting stuff to show.  HYE MNAS', '2002-06-27 02:50:00.000000', NULL, 0),
(70868, 2245, 1646, '<td valign="top">Creative!</td>', 'Creative!', '2002-06-10 04:37:00.000000', NULL, 1),
(70869, 2245, 789, '<td valign="top">Interesting interpetation.</td>', 'Interesting interpetation.', '2002-06-10 05:19:00.000000', NULL, 1),
(70870, 2245, 1, '<td valign="top">Ehhh.</td>', 'Ehhh.', '2002-06-10 10:04:00.000000', NULL, 1),
(70871, 2245, 1175, '<td valign="top">No offense to the finger, but if its gonna be part of a photo, have a manicure.  Besides the finger I like the photo.  It seems a bit bright on the left but not too bad.  Texture and color of the paper give it character.</td>', 'No offense to the finger, but if its gonna be part of a photo, have a manicure.  Besides the finger I like the photo.  It seems a bit bright on the left but not too bad.  Texture and color of the paper give it character.', '2002-06-10 11:12:00.000000', NULL, 1),
(70872, 2245, 1750, '<td valign="top">Interesting to see all the different interpretations. This one is clever.</td>', 'Interesting to see all the different interpretations. This one is clever.', '2002-06-10 11:20:00.000000', NULL, 1),
(70873, 2245, 772, '<td valign="top">This is a well-executed photograph... a little extra white balance or level adjustment would have possibly brightened up the page of the dictionary just a bit more... My overall problem with this particular shot is that it is outside my idea of the challenge topic.  It *is* on topic but it does not appeal to me as a great interpretation of this challenge...</td>', 'This is a well-executed photograph... a little extra white balance or level adjustment would have possibly brightened up the page of the dictionary just a bit more... My overall problem with this particular shot is that it is outside my idea of the challenge topic.  It *is* on topic but it does not appeal to me as a great interpretation of this challenge...', '2002-06-10 12:22:00.000000', NULL, 1),
(70874, 2245, 641, '<td valign="top">haha.. good interpretation. I might be off base here, but play with the white balance and see if you can get this a little brighter. Other than that, I like it.</td>', 'haha.. good interpretation. I might be off base here, but play with the white balance and see if you can get this a little brighter. Other than that, I like it.', '2002-06-10 12:24:00.000000', NULL, 1),
