(71218, 2270, 2109, '<td valign="top">hahahaha</td>', 'hahahaha', '2002-06-13 22:55:00.000000', NULL, 1),
(71219, 2270, 472, '<td valign="top">this is a very amusing picture, and creative too.  the only thing at all that takes away is the neighborhood in the background is just too visible.  if it had just been the paving stretching to the top of the screen or the if the trees/cars were more blurred, it would be a perfect picture!</td>', 'this is a very amusing picture, and creative too.  the only thing at all that takes away is the neighborhood in the background is just too visible.  if it had just been the paving stretching to the top of the screen or the if the trees/cars were more blurred, it would be a perfect picture!', '2002-06-15 22:54:00.000000', NULL, 1),
(71220, 2270, 2235, '<td valign="top">Nice idea. Concept done well. Not sure what I would have done to improve this for overall impact.</td>', 'Nice idea. Concept done well. Not sure what I would have done to improve this for overall impact.', '2002-06-16 09:12:00.000000', NULL, 1),
(71221, 2270, 1585, '<td valign="top">Great job. You showed us all what happens when you really want something. Keep taking pictures. You''re on your way to fame.</td>', 'Great job. You showed us all what happens when you really want something. Keep taking pictures. You''re on your way to fame.', '2002-06-18 13:06:00.000000', NULL, 0),
(71222, 2273, 1829, '<td valign="top">If you actually look into this picture, it gives you a feeling that you are travelling too!!  Great job.  This is a fantastic photo.</td>', 'If you actually look into this picture, it gives you a feeling that you are travelling too!!  Great job.  This is a fantastic photo.', '2002-06-10 01:42:00.000000', NULL, 1),
(71223, 2273, 1, '<td valign="top">Great shot, the lush green is awesome.  I love it how none of the car (or whatever you''re traveling in) is in view.  The gradual blur is awesome.</td>', 'Great shot, the lush green is awesome.  I love it how none of the car (or whatever you''re traveling in) is in view.  The gradual blur is awesome.', '2002-06-10 10:05:00.000000', NULL, 1),
(71224, 2273, 641, '<td valign="top">Woah.. I love the green and the motion in this!</td>', 'Woah.. I love the green and the motion in this!', '2002-06-10 12:26:00.000000', NULL, 1),
(71225, 2273, 1042, '<td valign="top">I don''t know about anyone else, but this photo makes me feel like I''m going into the picture...the more I look at it the more I feel like I''m actually moving forward...I like it...</td>', 'I don''t know about anyone else, but this photo makes me feel like I''m going into the picture...the more I look at it the more I feel like I''m actually moving forward...I like it...', '2002-06-10 12:45:00.000000', NULL, 1),
