(71227, 2273, 2000, '<td valign="top">I can fel the motion.</td>', 'I can fel the motion.', '2002-06-10 17:02:00.000000', NULL, 1),
(71228, 2273, 327, '<td valign="top">Nice job, clean, clear, sharp. Well done.</td>', 'Nice job, clean, clear, sharp. Well done.', '2002-06-10 18:29:00.000000', NULL, 1),
(71229, 2273, 616, '<td valign="top">nice motion effect</td>', 'nice motion effect', '2002-06-10 20:40:00.000000', NULL, 1),
(71230, 2273, 1543, '<td valign="top">love the speed</td>', 'love the speed', '2002-06-10 22:11:00.000000', NULL, 1),
(71231, 2273, 1897, '<td valign="top">car sick!</td>', 'car sick!', '2002-06-10 23:46:00.000000', NULL, 1),
