(71262, 2275, 983, '<td valign="top">Love the humor here! Shot is kinda plain I guess though.. But  I give ya a score above average.<br/></td>', 'Love the humor here! Shot is kinda plain I guess though.. But  I give ya a score above average.', '2002-06-13 00:28:00.000000', NULL, 1),
(71263, 2275, 1031, '<td valign="top">I almost wish ther was a hedge blocking the foreground headstones, leaving only the rearward unblurred ones to go with he motion blur of the foreground foliage &amp; fence.</td>', 'I almost wish ther was a hedge blocking the foreground headstones, leaving only the rearward unblurred ones to go with he motion blur of the foreground foliage & fence.', '2002-06-13 00:45:00.000000', NULL, 1),
(71264, 2275, 1, '<td valign="top">Nice idea, the motion blur is nice, I just wish it was a little less on the graves (like the ones further out).</td>', 'Nice idea, the motion blur is nice, I just wish it was a little less on the graves (like the ones further out).', '2002-06-13 09:43:00.000000', NULL, 1),
