(71400, 2279, 2109, '<td valign="top">excellent!</td>', 'excellent!', '2002-06-11 10:25:00.000000', NULL, 1),
(71401, 2279, 811, '<td valign="top">I think this is an excellent use of motion blur.  Interesting.</td>', 'I think this is an excellent use of motion blur.  Interesting.', '2002-06-11 17:41:00.000000', NULL, 1),
(71402, 2279, 2023, '<td valign="top">Awesome! would have liked more transparency.</td>', 'Awesome! would have liked more transparency.', '2002-06-11 21:39:00.000000', NULL, 1),
(71403, 2279, 1519, '<td valign="top">This turned out pretty cool! Nice!</td>', 'This turned out pretty cool! Nice!', '2002-06-11 23:09:00.000000', NULL, 1),
(71404, 2279, 1031, '<td valign="top">Pretty intense and effective blur -- makes it look as though someone''s discovered the secret of levitation.</td>', 'Pretty intense and effective blur -- makes it look as though someone''s discovered the secret of levitation.', '2002-06-12 03:53:00.000000', NULL, 1),
(71405, 2279, 1024, '<td valign="top">Very creative use of blur.  I can feel the motion.</td>', 'Very creative use of blur.  I can feel the motion.', '2002-06-12 11:33:00.000000', NULL, 1),
(71406, 2279, 1658, '<td valign="top">I really like this shot.  Good job, an well-shot interesting subject.</td>', 'I really like this shot.  Good job, an well-shot interesting subject.', '2002-06-12 12:12:00.000000', NULL, 1),
(71407, 2279, 1054, '<td valign="top">I can feel the wake of the bus just looking at this.</td>', 'I can feel the wake of the bus just looking at this.', '2002-06-12 18:51:00.000000', NULL, 1),
(71408, 2279, 255, '<td valign="top">i wonder how this would look if you had cropped this on the left to get the person out but still leave some of the ghostly bus in, and cropped it on the top right above the left light to give it a tighter framing? hmmm! still, i really like the concept of this shot. nice capture!</td>', 'i wonder how this would look if you had cropped this on the left to get the person out but still leave some of the ghostly bus in, and cropped it on the top right above the left light to give it a tighter framing? hmmm! still, i really like the concept of this shot. nice capture!', '2002-06-12 21:38:00.000000', NULL, 1),
(71409, 2279, 772, '<td valign="top">Very nice!  I can almost feel the breeze from this bus... your composition on this shot and the entire concept is great!  Good job!</td>', 'Very nice!  I can almost feel the breeze from this bus... your composition on this shot and the entire concept is great!  Good job!', '2002-06-13 14:03:00.000000', NULL, 1),
(71410, 2279, 208, '<td valign="top">nice use of stillness vs motion. if only the pedestrian hadn''t been moving, too...</td>', 'nice use of stillness vs motion. if only the pedestrian hadn''t been moving, too...', '2002-06-13 19:56:00.000000', NULL, 1),
(71411, 2279, 2204, '<td valign="top">Get rid of the person on the left and you have a good photo</td>', 'Get rid of the person on the left and you have a good photo', '2002-06-14 01:25:00.000000', NULL, 1),
(71412, 2279, 1037, '<td valign="top">Awesome! I love the action shots in this challenge. Those streaks of colour are really cool.</td>', 'Awesome! I love the action shots in this challenge. Those streaks of colour are really cool.', '2002-06-14 05:51:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(71413, 2279, 1707, '<td valign="top">nice color contrast!</td>', 'nice color contrast!', '2002-06-14 12:33:00.000000', NULL, 1),
(71414, 2279, 641, '<td valign="top">Cool effect!</td>', 'Cool effect!', '2002-06-15 15:14:00.000000', NULL, 1),
(71415, 2279, 2000, '<td valign="top">nice motion shot.</td>', 'nice motion shot.', '2002-06-16 23:43:00.000000', NULL, 1),
(71416, 2279, 1, '<td valign="top">Framing it a little to the right could''ve worked out better.</td>', 'Framing it a little to the right could''ve worked out better.', '2002-06-17 00:45:00.000000', NULL, 1),
(71417, 2280, 1, '<td valign="top">Wow, great shot.  Long exposure make it look almost like day.  Very well done -- s''all bling bling n''jank.</td>', 'Wow, great shot.  Long exposure make it look almost like day.  Very well done -- s''all bling bling n''jank.', '2002-06-10 02:06:00.000000', NULL, 1),
(71418, 2280, 2, '<td valign="top">Seems just a little too bright overall to me, and the building that''s fighting for the center of attention seems to be out of focus and slightly distracting.</td>', 'Seems just a little too bright overall to me, and the building that''s fighting for the center of attention seems to be out of focus and slightly distracting.', '2002-06-10 02:09:00.000000', NULL, 1),
(71419, 2280, 1360, '<td valign="top">Cliche''d shot, but well executed.</td>', 'Cliche''d shot, but well executed.', '2002-06-10 04:37:00.000000', NULL, 1),
(71420, 2280, 205, '<td valign="top">This would have been perfect had it not been ever so slightly tilted.</td>', 'This would have been perfect had it not been ever so slightly tilted.', '2002-06-10 06:28:00.000000', NULL, 1),
(71421, 2280, 1226, '<td valign="top">This is excellent. Looks like a nightlife/alcohol ad, and I mean that in a good way. I still see detail on the parked cars, and then all the blurs... I really like this shot.</td>', 'This is excellent. Looks like a nightlife/alcohol ad, and I mean that in a good way. I still see detail on the parked cars, and then all the blurs... I really like this shot.', '2002-06-10 12:17:00.000000', NULL, 1),
(71422, 2280, 1175, '<td valign="top">it looks like your camera was tilted a bit.  When taking pictures of landscape like this its usually better to keep your horizon completely horizontal.  You don''t have a horizon on this picture but I''m look at the right side of the building and it looks tilted.  Other than that I think its one of the better images in this challenge.</td>', 'it looks like your camera was tilted a bit.  When taking pictures of landscape like this its usually better to keep your horizon completely horizontal.  You don''t have a horizon on this picture but I''m look at the right side of the building and it looks tilted.  Other than that I think its one of the better images in this challenge.', '2002-06-10 14:15:00.000000', NULL, 1),
(71423, 2280, 1024, '<td valign="top">I had an idea to do something like this but could not find a proper vantage point.  This is very well captured.</td>', 'I had an idea to do something like this but could not find a proper vantage point.  This is very well captured.', '2002-06-10 15:15:00.000000', NULL, 1),
(71424, 2280, 1496, '<td valign="top">Love this picture!</td>', 'Love this picture!', '2002-06-10 15:52:00.000000', NULL, 1),
(71425, 2280, 327, '<td valign="top">Nice job here, well done.</td>', 'Nice job here, well done.', '2002-06-10 16:54:00.000000', NULL, 1),
(71426, 2280, 1005, '<td valign="top">Really like well done time exposure, Good job!  How many seconds?  (You must have a tripod)<br/>Photo 10 Creativity 8 Road 9 total 9</td>', 'Really like well done time exposure, Good job!  How many seconds?  (You must have a tripod)Photo 10 Creativity 8 Road 9 total 9', '2002-06-10 18:27:00.000000', NULL, 1),
(71427, 2280, 1944, '<td valign="top">Nicely done night piece.</td>', 'Nicely done night piece.', '2002-06-10 18:31:00.000000', NULL, 1),
(71428, 2280, 2091, '<td valign="top">Nice long exposure, Love shots like these :)</td>', 'Nice long exposure, Love shots like these :)', '2002-06-10 18:48:00.000000', NULL, 1),
(71429, 2280, 1009, '<td valign="top">Very nice night shot...</td>', 'Very nice night shot...', '2002-06-10 20:40:00.000000', NULL, 1),
(71430, 2280, 1759, '<td valign="top">Hey, where did all the cars go? Good spot for this and a decent idea for a difficult subject. Good job!</td>', 'Hey, where did all the cars go? Good spot for this and a decent idea for a difficult subject. Good job!', '2002-06-10 21:23:00.000000', NULL, 1),
(71431, 2280, 1543, '<td valign="top">beautiful colors and blur</td>', 'beautiful colors and blur', '2002-06-10 21:48:00.000000', NULL, 1),
(71432, 2280, 2123, '<td valign="top">Very nice!<br/></td>', 'Very nice!', '2002-06-10 22:31:00.000000', NULL, 1),
(71433, 2280, 1897, '<td valign="top">This should probably be a little darker, also, the scene is a little busy  but nice</td>', 'This should probably be a little darker, also, the scene is a little busy  but nice', '2002-06-10 23:42:00.000000', NULL, 1),
(71434, 2280, 811, '<td valign="top">This is a really cool shot.  I looked at it for awhile trying to decide what to do to improve it.  The two biggest lights really jump out, becoming the focal points of the picture, I think.  The curve is effective and emphasizing "motion" in the picture, but there is so much here, it is difficult to isolate any one thing as the main point of the picture (besides those lights).  Not much by way of suggestions, though, because cropping it causes you to lose road, etc.  Overall, I think it is a fairly effective shot.</td>', 'This is a really cool shot.  I looked at it for awhile trying to decide what to do to improve it.  The two biggest lights really jump out, becoming the focal points of the picture, I think.  The curve is effective and emphasizing "motion" in the picture, but there is so much here, it is difficult to isolate any one thing as the main point of the picture (besides those lights).  Not much by way of suggestions, though, because cropping it causes you to lose road, etc.  Overall, I think it is a fairly effective shot.', '2002-06-11 00:30:00.000000', NULL, 1),
(71435, 2280, 1962, '<td valign="top">Nice, lots of color.</td>', 'Nice, lots of color.', '2002-06-11 00:55:00.000000', NULL, 1),
(71436, 2280, 531, '<td valign="top">nice pic</td>', 'nice pic', '2002-06-11 00:59:00.000000', NULL, 1),
(71437, 2280, 2079, '<td valign="top">This is really a great shot - How much (if any) color correction was used?</td>', 'This is really a great shot - How much (if any) color correction was used?', '2002-06-11 02:03:00.000000', NULL, 1),
(71438, 2280, 1877, '<td valign="top">Where did you take this pic? A helicopter or something? Pretty cool shot..</td>', 'Where did you take this pic? A helicopter or something? Pretty cool shot..', '2002-06-11 02:57:00.000000', NULL, 1),
(71439, 2280, 1882, '<td valign="top">how do you do that?  I''ve always wanted to know.</td>', 'how do you do that?  I''ve always wanted to know.', '2002-06-11 12:30:00.000000', NULL, 1),
(71440, 2280, 878, '<td valign="top">Great colors</td>', 'Great colors', '2002-06-11 17:10:00.000000', NULL, 1),
(71441, 2280, 772, '<td valign="top">I like long exposures quite a bit... This shot does an excellent job of describing the ''on the road'' challenge... As I look at this image very closely, I believe I see some lack of clarity that may have been caused by camera shake.  I''m not sure how long this exposure is but I''m assuming it''s at least 2 or 3 seconds long.  If you were not on a tripod for this shot, I can see where the shake may have come from.  If you *were* on a tripod, you can still get camera shake from simply pressing the shutter release button.  When I do a shot like this, I setup my composition and framing and exposure, and then let the camera timer take the photo.  If the timer opens the shutter, you minimize your camera shake quite effectively... Nice shot!</td>', 'I like long exposures quite a bit... This shot does an excellent job of describing the ''on the road'' challenge... As I look at this image very closely, I believe I see some lack of clarity that may have been caused by camera shake.  I''m not sure how long this exposure is but I''m assuming it''s at least 2 or 3 seconds long.  If you were not on a tripod for this shot, I can see where the shake may have come from.  If you *were* on a tripod, you can still get camera shake from simply pressing the shutter release button.  When I do a shot like this, I setup my composition and framing and exposure, and then let the camera timer take the photo.  If the timer opens the shutter, you minimize your camera shake quite effectively... Nice shot!', '2002-06-11 18:29:00.000000', NULL, 1),
(71442, 2280, 885, '<td valign="top">I don''t like the title, but not going to mark down for that :)  It seems a little tilted though...the edge of the building isn''t quite parallel to the edge of the frame.  I like the colors though, and the curve of the road there is interesting.</td>', 'I don''t like the title, but not going to mark down for that :)  It seems a little tilted though...the edge of the building isn''t quite parallel to the edge of the frame.  I like the colors though, and the curve of the road there is interesting.', '2002-06-12 09:41:00.000000', NULL, 1),
(71443, 2280, 1446, '<td valign="top">Not sure what to look at here.  Sure is a lot going on. I like the movement and colors, but its a little overwhelming to me.</td>', 'Not sure what to look at here.  Sure is a lot going on. I like the movement and colors, but its a little overwhelming to me.', '2002-06-12 13:24:00.000000', NULL, 1),
(71444, 2280, 1054, '<td valign="top">Good execution!</td>', 'Good execution!', '2002-06-13 00:56:00.000000', NULL, 1),
(71445, 2280, 1041, '<td valign="top">I like the composition with the road curving around the building and the building following the ROT.  However, the building is leaning to the left - you need to straighten out your horizon - it''s very distracting.</td>', 'I like the composition with the road curving around the building and the building following the ROT.  However, the building is leaning to the left - you need to straighten out your horizon - it''s very distracting.', '2002-06-13 10:52:00.000000', NULL, 1),
(71446, 2280, 472, '<td valign="top">great exposure.  twinkly!  needs to be rotated a degree or 2 clock wise.  one of th ebetter pics in this challenge.</td>', 'great exposure.  twinkly!  needs to be rotated a degree or 2 clock wise.  one of th ebetter pics in this challenge.', '2002-06-13 11:11:00.000000', NULL, 1),
(71447, 2280, 2111, '<td valign="top">Wow, what a wonderful photo. I always love these types but this is extrodinary! 9</td>', 'Wow, what a wonderful photo. I always love these types but this is extrodinary! 9', '2002-06-13 11:43:00.000000', NULL, 1),
(71448, 2280, 1042, '<td valign="top">I love the lights in this..good job</td>', 'I love the lights in this..good job', '2002-06-13 14:15:00.000000', NULL, 1),
(71449, 2280, 2195, '<td valign="top">Excellent Pic!!!</td>', 'Excellent Pic!!!', '2002-06-13 22:45:00.000000', NULL, 1),
(71450, 2280, 2171, '<td valign="top">WoW!!  This is a terrific shot...great execuiton!  Slightly on the bright side for a night shot, but there are quite a few lights along the bridge.</td>', 'WoW!!  This is a terrific shot...great execuiton!  Slightly on the bright side for a night shot, but there are quite a few lights along the bridge.', '2002-06-13 23:30:00.000000', NULL, 1),
(71451, 2280, 2047, '<td valign="top">typical</td>', 'typical', '2002-06-15 00:08:00.000000', NULL, 1),
(71452, 2280, 2221, '<td valign="top">i love the lights at night!</td>', 'i love the lights at night!', '2002-06-15 15:50:00.000000', NULL, 1),
(71453, 2280, 2235, '<td valign="top">Excellent placement with areas available. Color and use of time delay is well done. Color and light only add more effect to this well done photo. Some may not like the building in the photo but I think it adds to the oveall effect.</td>', 'Excellent placement with areas available. Color and use of time delay is well done. Color and light only add more effect to this well done photo. Some may not like the building in the photo but I think it adds to the oveall effect.', '2002-06-16 08:58:00.000000', NULL, 1),
(71454, 2280, 772, '<td valign="top">Brumos, congrats on the win :)</td>', 'Brumos, congrats on the win :)', '2002-06-17 01:26:00.000000', NULL, 0),
(71455, 2280, 327, '<td valign="top">Very well done. LOVE the light and action. Congrats to you!!!!</td>', 'Very well done. LOVE the light and action. Congrats to you!!!!', '2002-06-17 12:03:00.000000', NULL, 0),
(71456, 2280, 693, '<td valign="top">Thanks everyone for your comments.<br/><br/>This photo was taken from my apartment balconey with a tripod which, unfortunatley, does not have a level bar; hence all the comments regarding the lack of a true vertical building/horizon.</td>', 'Thanks everyone for your comments.This photo was taken from my apartment balconey with a tripod which, unfortunatley, does not have a level bar; hence all the comments regarding the lack of a true vertical building/horizon.', '2002-06-17 16:34:00.000000', NULL, 0),
(71457, 2280, 1569, '<td valign="top">Congrats on winning!! Great pix!!</td>', 'Congrats on winning!! Great pix!!', '2002-06-17 21:37:00.000000', NULL, 0),
(71458, 2280, 441, '<td valign="top">superb long exp with minimal gear</td>', 'superb long exp with minimal gear', '2002-06-21 21:07:00.000000', NULL, 0),
(71459, 2282, 573, '<td valign="top">Nice picture, but I would liked to have seen a truck or cart ''On The Road''.</td>', 'Nice picture, but I would liked to have seen a truck or cart ''On The Road''.', '2002-06-10 13:38:00.000000', NULL, 1),
(71460, 2282, 885, '<td valign="top">pretty place.  wonder if getting down low near those flowers and shooting down the path there would have made a more interesting photo.</td>', 'pretty place.  wonder if getting down low near those flowers and shooting down the path there would have made a more interesting photo.', '2002-06-10 14:28:00.000000', NULL, 1),
(71461, 2282, 327, '<td valign="top">Pretty place, nice perspective, color.</td>', 'Pretty place, nice perspective, color.', '2002-06-10 16:54:00.000000', NULL, 1),
(71462, 2282, 1005, '<td valign="top">Good, clear photo, sure wish we could use a higher resolution....I really can''t see anything to critique, nor am I all that "excited" by this shot.  I like the potted plant on the left, very interesting.  Photo 8 Creativity 6 Road 7 total 7</td>', 'Good, clear photo, sure wish we could use a higher resolution....I really can''t see anything to critique, nor am I all that "excited" by this shot.  I like the potted plant on the left, very interesting.  Photo 8 Creativity 6 Road 7 total 7', '2002-06-10 20:05:00.000000', NULL, 1),
(71463, 2282, 1009, '<td valign="top">Nice use of angle...</td>', 'Nice use of angle...', '2002-06-10 21:04:00.000000', NULL, 1),
(71464, 2282, 806, '<td valign="top">I don''t like the composition. Sorry. I may have stepped out to the side to frame the smaller road with the bushes and flowers on the left, and the hedges on the right.<br/>As it stands, the subject appears to be the flowers and urn... not the road.</td>', 'I don''t like the composition. Sorry. I may have stepped out to the side to frame the smaller road with the bushes and flowers on the left, and the hedges on the right.As it stands, the subject appears to be the flowers and urn... not the road.', '2002-06-11 11:07:00.000000', NULL, 1),
(71465, 2282, 1944, '<td valign="top">I''m not sure you intended it, but I see a pun in the ''V'' in Vinyard. Anyway, I like it. Possibly it could use a little more detail in the hedge, maybe with the sun at a different angle. good focus and depth of field control.</td>', 'I''m not sure you intended it, but I see a pun in the ''V'' in Vinyard. Anyway, I like it. Possibly it could use a little more detail in the hedge, maybe with the sun at a different angle. good focus and depth of field control.', '2002-06-11 21:31:00.000000', NULL, 1),
(71466, 2282, 1313, '<td valign="top">Nice scenic shot but does not really have anything to do with the road, more of a nature shot.</td>', 'Nice scenic shot but does not really have anything to do with the road, more of a nature shot.', '2002-06-11 22:35:00.000000', NULL, 1),
(71467, 2282, 2135, '<td valign="top">Not a very interesting photo.  What is the subject of this image?  The flower bed or the road?  If it''s the flower bed, then it doesn''t relate to the challenge very well.  If it''s the road, then the photo should have been composed with it in mind.</td>', 'Not a very interesting photo.  What is the subject of this image?  The flower bed or the road?  If it''s the flower bed, then it doesn''t relate to the challenge very well.  If it''s the road, then the photo should have been composed with it in mind.', '2002-06-11 23:17:00.000000', NULL, 1),
(71468, 2282, 1, '<td valign="top">nice framing, though it just lacks something....</td>', 'nice framing, though it just lacks something....', '2002-06-12 11:50:00.000000', NULL, 1),
(71469, 2282, 1446, '<td valign="top">I enjoyed this composition, even with the bushes pretty much centered.  Focus is right on.  Great leading lines. An almost timeless shot.</td>', 'I enjoyed this composition, even with the bushes pretty much centered.  Focus is right on.  Great leading lines. An almost timeless shot.', '2002-06-12 13:22:00.000000', NULL, 1),
(71470, 2282, 472, '<td valign="top">sharp and crisp. a good photo. subject matter not particularly exciting, however.</td>', 'sharp and crisp. a good photo. subject matter not particularly exciting, however.', '2002-06-12 18:19:00.000000', NULL, 1),
(71471, 2282, 772, '<td valign="top">I can''t see much wrong with this photo on the technical side... I''m just not inspired by the subject...</td>', 'I can''t see much wrong with this photo on the technical side... I''m just not inspired by the subject...', '2002-06-12 18:20:00.000000', NULL, 1),
(71472, 2282, 1054, '<td valign="top">The focus here is the landscaping, not the road.  It gives me more of an "at home" feeling than an "on the road" one.  Also, the lighting is kind of flat; early morning or late day light might have been more attractive.</td>', 'The focus here is the landscaping, not the road.  It gives me more of an "at home" feeling than an "on the road" one.  Also, the lighting is kind of flat; early morning or late day light might have been more attractive.', '2002-06-12 21:52:00.000000', NULL, 1),
(71473, 2282, 2000, '<td valign="top">Photo is just grape.</td>', 'Photo is just grape.', '2002-06-16 23:13:00.000000', NULL, 1),
(71474, 2285, 885, '<td valign="top">The flag in the background is kind of a weird element.</td>', 'The flag in the background is kind of a weird element.', '2002-06-10 14:38:00.000000', NULL, 1),
(71475, 2285, 203, '<td valign="top">Gray and Gray.  The papers should be on the road (these are the silly comments I get so why should I give different).  Work on the black and white this is dull lifeless gray and gray.</td>', 'Gray and Gray.  The papers should be on the road (these are the silly comments I get so why should I give different).  Work on the black and white this is dull lifeless gray and gray.', '2002-06-10 15:13:00.000000', NULL, 1),
(71476, 2285, 772, '<td valign="top">This is an interesting photo but i think it''s a weak interpretation of the challenge... i do see the ''road'' in this shot but as I look at the photo, i ask myself "what is the subject of this photo?"</td>', 'This is an interesting photo but i think it''s a weak interpretation of the challenge... i do see the ''road'' in this shot but as I look at the photo, i ask myself "what is the subject of this photo?"', '2002-06-10 15:16:00.000000', NULL, 1),
(71477, 2285, 1175, '<td valign="top">Could have used a shot of contrast, a little dark too but that could be my screen.</td>', 'Could have used a shot of contrast, a little dark too but that could be my screen.', '2002-06-10 17:07:00.000000', NULL, 1),
(71478, 2285, 2010, '<td valign="top">Not good I have to say !</td>', 'Not good I have to say !', '2002-06-10 18:31:00.000000', NULL, 1),
(71479, 2285, 327, '<td valign="top">Fun work.</td>', 'Fun work.', '2002-06-10 18:34:00.000000', NULL, 1),
(71480, 2285, 1759, '<td valign="top">The B&amp;W works well here. It might have upset someone, but it would be better if the garbage can and other stuff behind the tree had been removed for this shot.</td>', 'The B&W works well here. It might have upset someone, but it would be better if the garbage can and other stuff behind the tree had been removed for this shot.', '2002-06-10 22:54:00.000000', NULL, 1),
(71481, 2285, 1944, '<td valign="top">Would have been better if there had been a little more tonal range. Looks kinna dull.</td>', 'Would have been better if there had been a little more tonal range. Looks kinna dull.', '2002-06-10 23:08:00.000000', NULL, 1),
(71482, 2285, 1897, '<td valign="top">poor use of BW, look at Balck and Chrome, or Foliage to see how it should be done.  I shot of a poorly lit curb is not very interesting</td>', 'poor use of BW, look at Balck and Chrome, or Foliage to see how it should be done.  I shot of a poorly lit curb is not very interesting', '2002-06-11 02:28:00.000000', NULL, 1),
(71483, 2285, 573, '<td valign="top">Shouldn''t this picture be in the ''On the Curb in Black and White'' challenge?  I like the composition but too flat grey scale wise for my taste.</td>', 'Shouldn''t this picture be in the ''On the Curb in Black and White'' challenge?  I like the composition but too flat grey scale wise for my taste.', '2002-06-11 11:56:00.000000', NULL, 1),
(71484, 2285, 1005, '<td valign="top">Dark, dark, dark , plus, how does this move/interest me?</td>', 'Dark, dark, dark , plus, how does this move/interest me?', '2002-06-11 20:30:00.000000', NULL, 1),
(71485, 2285, 1031, '<td valign="top">I think I would have tipped the bundle halfway into the gutter to emphasize the "discarded" aspect, and to appease any "fit-the-challenge" nit-pickers.</td>', 'I think I would have tipped the bundle halfway into the gutter to emphasize the "discarded" aspect, and to appease any "fit-the-challenge" nit-pickers.', '2002-06-12 03:37:00.000000', NULL, 1),
(71486, 2285, 1, '<td valign="top">Cool idea, just wish the papers were more framed in.  The tree gets in the way a lot, i would''ve moved the papers and shot from the other side of the tree/trash can.</td>', 'Cool idea, just wish the papers were more framed in.  The tree gets in the way a lot, i would''ve moved the papers and shot from the other side of the tree/trash can.', '2002-06-12 11:50:00.000000', NULL, 1),
(71487, 2285, 1041, '<td valign="top">I like how the edge of the pavement leads you through the photo.  Not sure about leading my eye down the drain though! ;)  I would probably have cropped the drain out if possible, tried to get the whole newspaper pile in the shot and adjusted my gamma and contrast - it looks a little gray on gray to me.</td>', 'I like how the edge of the pavement leads you through the photo.  Not sure about leading my eye down the drain though! ;)  I would probably have cropped the drain out if possible, tried to get the whole newspaper pile in the shot and adjusted my gamma and contrast - it looks a little gray on gray to me.', '2002-06-12 14:40:00.000000', NULL, 1),
(71488, 2285, 1054, '<td valign="top">I would have liked to see your subject (the newspapers) completely in the frame.</td>', 'I would have liked to see your subject (the newspapers) completely in the frame.', '2002-06-13 00:03:00.000000', NULL, 1),
