(71753, 2301, 1944, '<td valign="top">After you took her picture she still gave it to you? I think the photo could use a little ''snap''. You might lighten it a bit and increase the contrast some, it would make it a more effective statement.</td>', 'After you took her picture she still gave it to you? I think the photo could use a little ''snap''. You might lighten it a bit and increase the contrast some, it would make it a more effective statement.', '2002-06-11 21:38:00.000000', NULL, 1),
(71754, 2301, 1054, '<td valign="top">Well composed.</td>', 'Well composed.', '2002-06-13 00:39:00.000000', NULL, 1),
(71755, 2301, 1031, '<td valign="top">Expensive way to set up your shot...</td>', 'Expensive way to set up your shot...', '2002-06-13 02:02:00.000000', NULL, 1),
(71756, 2301, 878, '<td valign="top">Ahh a Chicago cop, doesnt looklike downtown, Bucktown?<br/><br/></td>', 'Ahh a Chicago cop, doesnt looklike downtown, Bucktown?', '2002-06-13 17:01:00.000000', NULL, 1),
(71757, 2301, 1024, '<td valign="top">This angle is much more interesting than if you had taken the photo head on.  The bright colors in her vest pull your eye toward her, so it might have been  better if she had been a little off center in the photo. Maybe cropped a little tighter??</td>', 'This angle is much more interesting than if you had taken the photo head on.  The bright colors in her vest pull your eye toward her, so it might have been  better if she had been a little off center in the photo. Maybe cropped a little tighter??', '2002-06-14 14:41:00.000000', NULL, 1),
(71758, 2301, 2140, '<td valign="top">why</td>', 'why', '2002-06-14 22:35:00.000000', NULL, 1),
(71759, 2301, 1379, '<td valign="top">Love the non-standard bag slung over her arm.....</td>', 'Love the non-standard bag slung over her arm.....', '2002-06-15 20:00:00.000000', NULL, 1),
(71760, 2301, 2235, '<td valign="top">Tells story but more of a snapshot. Angle and overall exposure a bit dark. Nice Idea for a "grap" shot.</td>', 'Tells story but more of a snapshot. Angle and overall exposure a bit dark. Nice Idea for a "grap" shot.', '2002-06-16 08:55:00.000000', NULL, 1),
(71761, 2301, 1, '<td valign="top">seems kinda snap shotty.</td>', 'seems kinda snap shotty.', '2002-06-17 00:54:00.000000', NULL, 1),
(71762, 2302, 327, '<td valign="top">lol, love the title. Cute, clever shot.</td>', 'lol, love the title. Cute, clever shot.', '2002-06-10 18:15:00.000000', NULL, 1),
(71763, 2302, 2010, '<td valign="top">Not very modern.....hmmmmmm.....</td>', 'Not very modern.....hmmmmmm.....', '2002-06-10 18:42:00.000000', NULL, 1),
(71764, 2302, 1759, '<td valign="top">You''ve taken the mundane and made it special. Good macro shot and creative use of resources!</td>', 'You''ve taken the mundane and made it special. Good macro shot and creative use of resources!', '2002-06-10 21:48:00.000000', NULL, 1),
