(71816, 2309, 1313, '<td valign="top">street out of focus too close up</td>', 'street out of focus too close up', '2002-06-11 18:27:00.000000', NULL, 1),
(71817, 2309, 1446, '<td valign="top">Not a big fan of oof items in the foreground, but the contrast is good and there is good use of b&amp;w.</td>', 'Not a big fan of oof items in the foreground, but the contrast is good and there is good use of b&w.', '2002-06-11 18:34:00.000000', NULL, 1),
(71818, 2309, 1519, '<td valign="top">This is a unique view.  Very crisp and clear.  Good in b/w.  Definitely on the road.  Neat angle.</td>', 'This is a unique view.  Very crisp and clear.  Good in b/w.  Definitely on the road.  Neat angle.', '2002-06-11 23:21:00.000000', NULL, 1),
(71819, 2309, 2023, '<td valign="top">Simple and to the point, great shot!</td>', 'Simple and to the point, great shot!', '2002-06-12 13:16:00.000000', NULL, 1),
(71820, 2309, 1054, '<td valign="top">Nice interpretation and composition.</td>', 'Nice interpretation and composition.', '2002-06-12 22:09:00.000000', NULL, 1),
(71821, 2309, 2182, '<td valign="top">Great work</td>', 'Great work', '2002-06-13 01:14:00.000000', NULL, 1),
(71822, 2309, 472, '<td valign="top">this makes me ''tire''d out, lol. jk.  nice abstract, although subject matter is a bit static (ie not particularly interesting).</td>', 'this makes me ''tire''d out, lol. jk.  nice abstract, although subject matter is a bit static (ie not particularly interesting).', '2002-06-13 11:08:00.000000', NULL, 1),
(71823, 2309, 1041, '<td valign="top">I love textures, macros and close-ups.  This one''s well executed.  Top 10.</td>', 'I love textures, macros and close-ups.  This one''s well executed.  Top 10.', '2002-06-13 12:00:00.000000', NULL, 1),
(71824, 2309, 2047, '<td valign="top">interesting angle</td>', 'interesting angle', '2002-06-15 00:06:00.000000', NULL, 1),
(71825, 2309, 1908, '<td valign="top">more DOF req to make a better image</td>', 'more DOF req to make a better image', '2002-06-15 03:04:00.000000', NULL, 1),
(71826, 2310, 1122, '<td valign="top">The sky is clear, the clouds are beautiful and the colour is sharp.<br/>Great picture!!</td>', 'The sky is clear, the clouds are beautiful and the colour is sharp.Great picture!!', '2002-06-10 03:04:00.000000', NULL, 1),
(71827, 2310, 1360, '<td valign="top">We really like stop signs here, dont we? ;)</td>', 'We really like stop signs here, dont we? ;)', '2002-06-10 04:44:00.000000', NULL, 1),
(71828, 2310, 142, '<td valign="top">I like the colors in this photo and the placement of the stop sign.  Great photo.</td>', 'I like the colors in this photo and the placement of the stop sign.  Great photo.', '2002-06-10 09:31:00.000000', NULL, 1),
(71829, 2310, 1, '<td valign="top">Wow great shot.  Very crisp, very clear.  Fade from lightblue-&amp;gt;darkerblue is really nice and works well with the red.</td>', 'Wow great shot.  Very crisp, very clear.  Fade from lightblue-&gt;darkerblue is really nice and works well with the red.', '2002-06-10 12:13:00.000000', NULL, 1),
(71830, 2310, 641, '<td valign="top">beautiful reds and blues... such rich colors. very nice</td>', 'beautiful reds and blues... such rich colors. very nice', '2002-06-10 12:21:00.000000', NULL, 1),
(71831, 2310, 1569, '<td valign="top">Nice arrangment!!!</td>', 'Nice arrangment!!!', '2002-06-10 13:34:00.000000', NULL, 1),
(71832, 2310, 1779, '<td valign="top">wow! great shor worthy of a stock bank.</td>', 'wow! great shor worthy of a stock bank.', '2002-06-10 14:57:00.000000', NULL, 1),
(71833, 2310, 885, '<td valign="top">Very clean.</td>', 'Very clean.', '2002-06-10 16:27:00.000000', NULL, 1),
(71834, 2310, 1005, '<td valign="top">Wow, almost surreal color, wonderful.    I really like the shading of the sky, dark blue to light, very nice.  I think you have a possible winner here.  Itsy, bitsy nit time:  it''s probably too much to ask, but the stop sign doesn''t line up with the edge of the photo, could you have reached a little higher?  (yeah, super nit)<br/>Photo 10 Creativity 9 Road 10 Total 10  (keep up the good work!)</td>', 'Wow, almost surreal color, wonderful.    I really like the shading of the sky, dark blue to light, very nice.  I think you have a possible winner here.  Itsy, bitsy nit time:  it''s probably too much to ask, but the stop sign doesn''t line up with the edge of the photo, could you have reached a little higher?  (yeah, super nit)Photo 10 Creativity 9 Road 10 Total 10  (keep up the good work!)', '2002-06-10 17:39:00.000000', NULL, 1),
