(71932, 2314, 1856, '<td valign="top">Love the window background.</td>', 'Love the window background.', '2002-06-10 13:27:00.000000', NULL, 1),
(71933, 2314, 203, '<td valign="top">Like Jerry Garcia, Jack is dead.  Let him go.</td>', 'Like Jerry Garcia, Jack is dead.  Let him go.', '2002-06-10 15:23:00.000000', NULL, 1),
(71934, 2314, 885, '<td valign="top">Hehe...is that posed, or were you just really lucky to catch someone reading that?  The lighting is pretty good considering you can''t really control it, and I like the blurred window.</td>', 'Hehe...is that posed, or were you just really lucky to catch someone reading that?  The lighting is pretty good considering you can''t really control it, and I like the blurred window.', '2002-06-10 16:10:00.000000', NULL, 1),
(71935, 2314, 1175, '<td valign="top">Great title.  Great choice for the book as well.  I wonder how it would look if you just cropped off the bottom and some of the right, and maybe have the reader hold the book a little higher, about 75% the distance to their head now.  Then all you need is a little front light to fill in some of those dark spots and you''ve got a great picture. :)  Overall very clever.</td>', 'Great title.  Great choice for the book as well.  I wonder how it would look if you just cropped off the bottom and some of the right, and maybe have the reader hold the book a little higher, about 75% the distance to their head now.  Then all you need is a little front light to fill in some of those dark spots and you''ve got a great picture. :)  Overall very clever.', '2002-06-10 16:58:00.000000', NULL, 1),
(71936, 2314, 1944, '<td valign="top">It fits, doesn''t it?</td>', 'It fits, doesn''t it?', '2002-06-10 18:31:00.000000', NULL, 1),
(71937, 2314, 327, '<td valign="top">Nice work, I like this.</td>', 'Nice work, I like this.', '2002-06-10 18:35:00.000000', NULL, 1),
(71938, 2314, 1009, '<td valign="top">Cool blur effect in the background. Neat idea...</td>', 'Cool blur effect in the background. Neat idea...', '2002-06-10 20:48:00.000000', NULL, 1),
(71939, 2314, 1313, '<td valign="top">Too much blur</td>', 'Too much blur', '2002-06-10 21:08:00.000000', NULL, 1),
(71940, 2314, 1983, '<td valign="top">Great shot. I like how you captured the view out the back window.</td>', 'Great shot. I like how you captured the view out the back window.', '2002-06-10 23:43:00.000000', NULL, 1),
(71941, 2314, 714, '<td valign="top">creativety  6   interesting   5  focus 9  framing  8=7</td>', 'creativety  6   interesting   5  focus 9  framing  8=7', '2002-06-11 01:20:00.000000', NULL, 1),
(71942, 2314, 1897, '<td valign="top">It would work better as a nude, but good effort</td>', 'It would work better as a nude, but good effort', '2002-06-11 02:20:00.000000', NULL, 1),
(71943, 2314, 1907, '<td valign="top">hmm... i notice the title of your book :D</td>', 'hmm... i notice the title of your book :D', '2002-06-11 04:52:00.000000', NULL, 1),
(71944, 2314, 1446, '<td valign="top">I like the motion in the background. Good choice of ''reading material'' :)  The window seems to cut the shot in half.</td>', 'I like the motion in the background. Good choice of ''reading material'' :)  The window seems to cut the shot in half.', '2002-06-11 10:51:00.000000', NULL, 1),
(71945, 2314, 2111, '<td valign="top">I give this a D (7)</td>', 'I give this a D (7)', '2002-06-11 16:28:00.000000', NULL, 1),
(71946, 2314, 1005, '<td valign="top">Bus or train?  This is a really nice picture.  The motion says ''we are going fast!'', whence the train question.  Brown pant disappear above the knees, oops.  (Was her hair really blonde and orange? No evidence of color enhancement)  Mostly a very nice job, though some might question the road aspect.  Photo 8 Creativity 6 Road (if bus) 7 total 7</td>', 'Bus or train?  This is a really nice picture.  The motion says ''we are going fast!'', whence the train question.  Brown pant disappear above the knees, oops.  (Was her hair really blonde and orange? No evidence of color enhancement)  Mostly a very nice job, though some might question the road aspect.  Photo 8 Creativity 6 Road (if bus) 7 total 7', '2002-06-11 19:19:00.000000', NULL, 1),
(71947, 2314, 1227, '<td valign="top">pretty lady</td>', 'pretty lady', '2002-06-12 01:04:00.000000', NULL, 1),
(71948, 2314, 1041, '<td valign="top">My eyes always get hung up on the thumbnail - she looks like someone I knew years ago.  Eerie.  Good use of ROT.  Like the focused inside with the blurred world zooming by outside.</td>', 'My eyes always get hung up on the thumbnail - she looks like someone I knew years ago.  Eerie.  Good use of ROT.  Like the focused inside with the blurred world zooming by outside.', '2002-06-13 15:21:00.000000', NULL, 1),
(71949, 2314, 772, '<td valign="top">I like the motion blur that you caught in the reflections on the window behind the subject in this photo... She looks relaxed... do you know her or was this a ''voyeur'' shot on a bus?  Good work!</td>', 'I like the motion blur that you caught in the reflections on the window behind the subject in this photo... She looks relaxed... do you know her or was this a ''voyeur'' shot on a bus?  Good work!', '2002-06-13 15:59:00.000000', NULL, 1),
(71950, 2314, 89, '<td valign="top">steinbeck?</td>', 'steinbeck?', '2002-06-13 22:34:00.000000', NULL, 1),
(71951, 2314, 2126, '<td valign="top">I like the contrast of the movement in the background with absolutely no blur in the foreground</td>', 'I like the contrast of the movement in the background with absolutely no blur in the foreground', '2002-06-14 19:13:00.000000', NULL, 1),
(71952, 2314, 2047, '<td valign="top">like the blur</td>', 'like the blur', '2002-06-15 00:05:00.000000', NULL, 1),
(71953, 2314, 811, '<td valign="top">had to look at it a couple of times before I "discovered" the title of the book.  It was almost too subtle, but an excellent picture, nonetheless.</td>', 'had to look at it a couple of times before I "discovered" the title of the book.  It was almost too subtle, but an excellent picture, nonetheless.', '2002-06-15 00:28:00.000000', NULL, 1),
(71954, 2314, 1037, '<td valign="top">Oh, there''s the Kerouac reference :). This is one of my favourites. It gets a 10 :)</td>', 'Oh, there''s the Kerouac reference :). This is one of my favourites. It gets a 10 :)', '2002-06-16 03:28:00.000000', NULL, 1),
(71955, 2314, 2235, '<td valign="top">Excellent lighting. Show center of interest to best exposure. Concept well done. Blurred background added to idea of movement. Not as focused on idea of "on the road" as title (in my opinion) but well done.</td>', 'Excellent lighting. Show center of interest to best exposure. Concept well done. Blurred background added to idea of movement. Not as focused on idea of "on the road" as title (in my opinion) but well done.', '2002-06-16 09:32:00.000000', NULL, 1),
(71956, 2314, 2000, '<td valign="top">She must be reading that for a book report or something.</td>', 'She must be reading that for a book report or something.', '2002-06-17 00:32:00.000000', NULL, 1),
(71957, 2314, 1, '<td valign="top">Nicely framed, motrion blur works well.</td>', 'Nicely framed, motrion blur works well.', '2002-06-17 00:37:00.000000', NULL, 1),
(71958, 2314, 2586, '<td valign="top">Today is July 23 (browsing through profiles and archives)  and i have no idea where this comment goes but would like to me it anyway. This is a very nice pic and i read the comments. One said to crop it just below the hand or around the knee. So, i played a little with the window and scrolling. And golly, if you were to crop it like that, the pic gains tremendously in strength. There would a perfect balance between the window, her face and the book. The eye moves around from one light area to another in a circular fashion then as well without being stuck in the dark area of the pants. The book is a subtle idea and the window is just GRAND ! Hope you did some cropjuggling with this pic since then :)</td>', 'Today is July 23 (browsing through profiles and archives)  and i have no idea where this comment goes but would like to me it anyway. This is a very nice pic and i read the comments. One said to crop it just below the hand or around the knee. So, i played a little with the window and scrolling. And golly, if you were to crop it like that, the pic gains tremendously in strength. There would a perfect balance between the window, her face and the book. The eye moves around from one light area to another in a circular fashion then as well without being stuck in the dark area of the pants. The book is a subtle idea and the window is just GRAND ! Hope you did some cropjuggling with this pic since then :)', '2002-07-24 03:26:00.000000', NULL, 0),
(71959, 2315, 2, '<td valign="top">Such an impressively framed/focused/composed photograph for obviously being in a moving car.  The contrasts of this photo are outstanding, and I just love the entire composition.  Great job.</td>', 'Such an impressively framed/focused/composed photograph for obviously being in a moving car.  The contrasts of this photo are outstanding, and I just love the entire composition.  Great job.', '2002-06-10 10:35:00.000000', NULL, 1),
(71960, 2315, 573, '<td valign="top">I hate rush hour traffic too.  But nice picture goob contrast, I would like more detail in the shadows.</td>', 'I hate rush hour traffic too.  But nice picture goob contrast, I would like more detail in the shadows.', '2002-06-10 13:59:00.000000', NULL, 1),
(71961, 2315, 641, '<td valign="top">Great framing job.</td>', 'Great framing job.', '2002-06-10 15:28:00.000000', NULL, 1),
(71962, 2315, 1897, '<td valign="top">interesting affect.  The subdued color is great, I think this is the best, I am bumping you up to a 9</td>', 'interesting affect.  The subdued color is great, I think this is the best, I am bumping you up to a 9', '2002-06-10 15:43:00.000000', NULL, 1),
(71963, 2315, 327, '<td valign="top">Neat perspective.</td>', 'Neat perspective.', '2002-06-10 18:14:00.000000', NULL, 1),
(71964, 2315, 1759, '<td valign="top">I like the idea of framing the bridge with a tunnel. It might look better if taken from the middle late so the bridge could be perfectly centered.</td>', 'I like the idea of framing the bridge with a tunnel. It might look better if taken from the middle late so the bridge could be perfectly centered.', '2002-06-10 20:59:00.000000', NULL, 1),
(71965, 2315, 1313, '<td valign="top">Too dark</td>', 'Too dark', '2002-06-10 21:21:00.000000', NULL, 1),
(71966, 2315, 1944, '<td valign="top">Fiive days a week for thirty years:(</td>', 'Fiive days a week for thirty years:(', '2002-06-10 23:39:00.000000', NULL, 1),
(71967, 2315, 156, '<td valign="top">great title! too dark tho</td>', 'great title! too dark tho', '2002-06-11 10:26:00.000000', NULL, 1),
(71968, 2315, 1540, '<td valign="top">good shot, but this would have been an incredible shot if you could have gotten shot from the center..</td>', 'good shot, but this would have been an incredible shot if you could have gotten shot from the center..', '2002-06-11 11:27:00.000000', NULL, 1),
(71969, 2315, 138, '<td valign="top">i like!</td>', 'i like!', '2002-06-11 17:58:00.000000', NULL, 1),
(71970, 2315, 1031, '<td valign="top">Been there, but never with the camera out...<br/><br/>"This morning I saw a terrifying sight. People running -- TO WORK!"<br/>--Paraphrased from Murray Burns, A Thousand Clowns</td>', 'Been there, but never with the camera out..."This morning I saw a terrifying sight. People running -- TO WORK!"--Paraphrased from Murray Burns, A Thousand Clowns', '2002-06-12 03:41:00.000000', NULL, 1),
(71971, 2315, 885, '<td valign="top">I thought B&amp;W at first, but the tailights are a little red.  I like how the extreme desaturation simplifies what otherwise might have been a pretty busy image.  I like the off centered-ness of the arch too, it makes you feel more ''in the middle'' of things than if it had been centered.</td>', 'I thought B&W at first, but the tailights are a little red.  I like how the extreme desaturation simplifies what otherwise might have been a pretty busy image.  I like the off centered-ness of the arch too, it makes you feel more ''in the middle'' of things than if it had been centered.', '2002-06-12 09:58:00.000000', NULL, 1),
(71972, 2315, 1024, '<td valign="top">I like the use of framing and the black and white.</td>', 'I like the use of framing and the black and white.', '2002-06-12 12:38:00.000000', NULL, 1),
(71973, 2315, 772, '<td valign="top">I think this is an excellent idea for a photo... my only problem with it is that I think it should have been taken just a little closer to the end of the tunnel where the opening filled a little more of the image.. The tunnel opening is GREAT framing for this shot but I think, for the most part, there is too much darkness around the edges here to suit me... Being closer to the edge *or* zooming out a little more may have been a nice improvement.  Im glad i''m not driving in this much traffic :) Good work!</td>', 'I think this is an excellent idea for a photo... my only problem with it is that I think it should have been taken just a little closer to the end of the tunnel where the opening filled a little more of the image.. The tunnel opening is GREAT framing for this shot but I think, for the most part, there is too much darkness around the edges here to suit me... Being closer to the edge *or* zooming out a little more may have been a nice improvement.  Im glad i''m not driving in this much traffic :) Good work!', '2002-06-12 18:22:00.000000', NULL, 1),
(71974, 2315, 1054, '<td valign="top">Well captured.</td>', 'Well captured.', '2002-06-12 21:36:00.000000', NULL, 1),
(71975, 2315, 1042, '<td valign="top">I like the use of black and white here. Using color would have taken a lot away from it I think. I love the focus of the bridge up ahead and the tilte is perfect...I feel that way everytime I get in traffic going to work.</td>', 'I like the use of black and white here. Using color would have taken a lot away from it I think. I love the focus of the bridge up ahead and the tilte is perfect...I feel that way everytime I get in traffic going to work.', '2002-06-13 14:13:00.000000', NULL, 1),
(71976, 2315, 1037, '<td valign="top">Nice bold composition. It seems very desaturated, but not black and white, however this just sets off the shapes of the structures more. I like it :)</td>', 'Nice bold composition. It seems very desaturated, but not black and white, however this just sets off the shapes of the structures more. I like it :)', '2002-06-14 06:18:00.000000', NULL, 1),
(71977, 2315, 47, '<td valign="top">i concur.</td>', 'i concur.', '2002-06-15 15:26:00.000000', NULL, 1),
(71978, 2315, 2000, '<td valign="top">nice b/w shot.</td>', 'nice b/w shot.', '2002-06-16 23:51:00.000000', NULL, 1),
(71979, 2315, 1, '<td valign="top">Very nice, would work pretty nice for shadows too eh?</td>', 'Very nice, would work pretty nice for shadows too eh?', '2002-06-17 00:20:00.000000', NULL, 1),
(71980, 2316, 656, '<td valign="top">reminds me a bit of a classic shot of the guy jumping a puddle...<br/><br/></td>', 'reminds me a bit of a classic shot of the guy jumping a puddle...', '2002-06-10 13:06:00.000000', NULL, 1),
(71981, 2316, 885, '<td valign="top">I like that blurred girl especially.  It might have helped to focus more on one of the elements in this photo more, rather than the whole thing, which is a little busy for my tastes.</td>', 'I like that blurred girl especially.  It might have helped to focus more on one of the elements in this photo more, rather than the whole thing, which is a little busy for my tastes.', '2002-06-10 14:25:00.000000', NULL, 1),
(71982, 2316, 772, '<td valign="top">There are indeed people on the road in this photo.  When this photo ''speaks'' to me, it is whispering ''hustle and bustle'' in my ear moreso than my ''own'' concept of ''on the road''.  The overall artistic impact of this photo doesn''t really grab me but the challenge has been met :)</td>', 'There are indeed people on the road in this photo.  When this photo ''speaks'' to me, it is whispering ''hustle and bustle'' in my ear moreso than my ''own'' concept of ''on the road''.  The overall artistic impact of this photo doesn''t really grab me but the challenge has been met :)', '2002-06-10 15:58:00.000000', NULL, 1),
(71983, 2316, 327, '<td valign="top">Good action shot, interesting too.</td>', 'Good action shot, interesting too.', '2002-06-10 17:00:00.000000', NULL, 1),
(71984, 2316, 1005, '<td valign="top">This is a really good idea.  The runner jaywalking iis a great touch.  Now for the buts......Look at the street sign hung on the lamp, almost completely washed out.  Next, sorry, but you must have a low end camera, it makes a difference when you have lots of "data" like this.  Red coat girl for example, she has a face and a nose, but that''s all I can make out.  I am surprised I can tell she is smoking, probably.  This lack of detail hurts your overall image.  Sorry to pick on your hardware, but it''s true.<br/>Photo 7 Creativity 6 Road 7 total 7  (IF I am wrong, and you have a multi-mega pixel camera, please subtract two points for lack of detail)</td>', 'This is a really good idea.  The runner jaywalking iis a great touch.  Now for the buts......Look at the street sign hung on the lamp, almost completely washed out.  Next, sorry, but you must have a low end camera, it makes a difference when you have lots of "data" like this.  Red coat girl for example, she has a face and a nose, but that''s all I can make out.  I am surprised I can tell she is smoking, probably.  This lack of detail hurts your overall image.  Sorry to pick on your hardware, but it''s true.Photo 7 Creativity 6 Road 7 total 7  (IF I am wrong, and you have a multi-mega pixel camera, please subtract two points for lack of detail)', '2002-06-10 18:50:00.000000', NULL, 1),
(71985, 2316, 714, '<td valign="top">Creativety 7  interesting 5   focus  5   framing 7  = 6</td>', 'Creativety 7  interesting 5   focus  5   framing 7  = 6', '2002-06-11 01:17:00.000000', NULL, 1),
(71986, 2316, 573, '<td valign="top">I feel this picture would be best if saved for the ''Crossing the Road'' challenge.  good use of blur to show people running.  This is ine of those intersections where you can cross diagonaly? Neet! I''ve always wanted to do that.</td>', 'I feel this picture would be best if saved for the ''Crossing the Road'' challenge.  good use of blur to show people running.  This is ine of those intersections where you can cross diagonaly? Neet! I''ve always wanted to do that.', '2002-06-11 13:43:00.000000', NULL, 1),
(71987, 2316, 1944, '<td valign="top">I like what you were trying to say, but I think some of the decisions you made in resolution/compression compromised its visual impact. On my monitor the people, especially those at the left middle crossing the street aren''t as sharp as they should be.</td>', 'I like what you were trying to say, but I think some of the decisions you made in resolution/compression compromised its visual impact. On my monitor the people, especially those at the left middle crossing the street aren''t as sharp as they should be.', '2002-06-11 21:50:00.000000', NULL, 1),
(71988, 2316, 862, '<td valign="top">I like this composition.  There is a lot going on here.  I feel that it would be a stronger photo if the woman in red was in focus.</td>', 'I like this composition.  There is a lot going on here.  I feel that it would be a stronger photo if the woman in red was in focus.', '2002-06-12 10:32:00.000000', NULL, 1),
(71989, 2316, 1054, '<td valign="top">The focus is not quite right to me, I would have focused on the woman in red.</td>', 'The focus is not quite right to me, I would have focused on the woman in red.', '2002-06-12 23:58:00.000000', NULL, 1),
(71990, 2316, 1041, '<td valign="top">Nice how some people are blurred because in a hurry and others are not.</td>', 'Nice how some people are blurred because in a hurry and others are not.', '2002-06-14 14:23:00.000000', NULL, 1),
(71991, 2316, 2047, '<td valign="top">kinda boring and typical</td>', 'kinda boring and typical', '2002-06-15 00:04:00.000000', NULL, 1),
(71992, 2316, 1, '<td valign="top">Very busy, a nice depiction of an interesection. Can you get a wider angle?</td>', 'Very busy, a nice depiction of an interesection. Can you get a wider angle?', '2002-06-17 00:39:00.000000', NULL, 1),
(71993, 2322, 436, '<td valign="top">good catch!</td>', 'good catch!', '2002-06-10 10:41:00.000000', NULL, 1),
(71994, 2322, 1, '<td valign="top">Nice framing, would work great in a newspaper.</td>', 'Nice framing, would work great in a newspaper.', '2002-06-10 11:14:00.000000', NULL, 1),
(71995, 2322, 1944, '<td valign="top">so what? What''s so interesting?</td>', 'so what? What''s so interesting?', '2002-06-10 16:18:00.000000', NULL, 1),
(71996, 2322, 327, '<td valign="top">LOL Fun capture. Little over sharpened.</td>', 'LOL Fun capture. Little over sharpened.', '2002-06-10 18:16:00.000000', NULL, 1),
(71997, 2322, 1313, '<td valign="top">OK pic, but nothing special looks like a typcial street scene.</td>', 'OK pic, but nothing special looks like a typcial street scene.', '2002-06-10 21:04:00.000000', NULL, 1),
(71998, 2322, 554, '<td valign="top">they do this at 40 mph where I live</td>', 'they do this at 40 mph where I live', '2002-06-10 23:04:00.000000', NULL, 1),
(71999, 2322, 714, '<td valign="top">creativety 6  interesting 5   focus 7  framing 6 = 6</td>', 'creativety 6  interesting 5   focus 7  framing 6 = 6', '2002-06-11 01:53:00.000000', NULL, 1),
(72000, 2322, 1897, '<td valign="top">this is so muddled. it is blurry, yet over sharp.  the colors are faded, the framing is horrible, what was photo worthy here?</td>', 'this is so muddled. it is blurry, yet over sharp.  the colors are faded, the framing is horrible, what was photo worthy here?', '2002-06-11 02:33:00.000000', NULL, 1),
(72001, 2322, 772, '<td valign="top">i like nice new fresh lines :)</td>', 'i like nice new fresh lines :)', '2002-06-11 10:26:00.000000', NULL, 1),
(72002, 2322, 1005, '<td valign="top">With police escort?  Very nice photo.  I wish scenery shots would be allowed to use high res.  Phone lines get squiggly/broken and text isn''t very clear, but these are gripes about the resolution we have to use, not your photo.   Nits:  A bit dark, see the worker in front? (sort of);  Blank sky  -  I don''t know how to fix it, but I don''t like it (sorry).  <br/>Photo 8 Creativity 7 Road 7 total 7</td>', 'With police escort?  Very nice photo.  I wish scenery shots would be allowed to use high res.  Phone lines get squiggly/broken and text isn''t very clear, but these are gripes about the resolution we have to use, not your photo.   Nits:  A bit dark, see the worker in front? (sort of);  Blank sky  -  I don''t know how to fix it, but I don''t like it (sorry).  Photo 8 Creativity 7 Road 7 total 7', '2002-06-11 19:28:00.000000', NULL, 1),
(72003, 2322, 1054, '<td valign="top">This feels rather snapshotty to me.</td>', 'This feels rather snapshotty to me.', '2002-06-12 22:12:00.000000', NULL, 1),
(72004, 2322, 1379, '<td valign="top">What a random, interesting thing to catch in action!</td>', 'What a random, interesting thing to catch in action!', '2002-06-12 22:17:00.000000', NULL, 1),
(72005, 2322, 2009, '<td valign="top">How strange. this looks like a colorized black and white.  Beth</td>', 'How strange. this looks like a colorized black and white.  Beth', '2002-06-14 23:45:00.000000', NULL, 1),
(72006, 2322, 472, '<td valign="top">although it is photographed well, it was hard to get a good subject this week ..</td>', 'although it is photographed well, it was hard to get a good subject this week ..', '2002-06-15 23:03:00.000000', NULL, 1),
(72007, 2323, 885, '<td valign="top">I think the fact that the lines are not parallel/perpendicular to the edges of the frame is detrimental.  Otherwise, interesting patterns.</td>', 'I think the fact that the lines are not parallel/perpendicular to the edges of the frame is detrimental.  Otherwise, interesting patterns.', '2002-06-10 13:58:00.000000', NULL, 1),
(72008, 2323, 1944, '<td valign="top">Doesn''t  say anything. Not sharp</td>', 'Doesn''t  say anything. Not sharp', '2002-06-10 16:16:00.000000', NULL, 1),
(72009, 2323, 772, '<td valign="top">A subway/train is a bit of a strectch for me as being ''on the road'' but I will not try to argue that particular point with this photo...   As for the composition and framing of this shot, I think I would like to see more of the passengers through the window.  The number 2 on the train is definitely pulling my attention away from the possible better subjects in the photo.  This shot could have potentially produced more impact if I was looking down the edge of the train towards one end of it.... It should have also reduced the amount of light glare that is boucing back towards the camera from the upper left portion of the frame...</td>', 'A subway/train is a bit of a strectch for me as being ''on the road'' but I will not try to argue that particular point with this photo...   As for the composition and framing of this shot, I think I would like to see more of the passengers through the window.  The number 2 on the train is definitely pulling my attention away from the possible better subjects in the photo.  This shot could have potentially produced more impact if I was looking down the edge of the train towards one end of it.... It should have also reduced the amount of light glare that is boucing back towards the camera from the upper left portion of the frame...', '2002-06-10 17:46:00.000000', NULL, 1),
(72010, 2323, 1877, '<td valign="top">Hmm.. Maybe black and white, and without the 2/people -- kinda distracting.. That lady sure is happy tho!</td>', 'Hmm.. Maybe black and white, and without the 2/people -- kinda distracting.. That lady sure is happy tho!', '2002-06-10 18:36:00.000000', NULL, 1),
(72011, 2323, 327, '<td valign="top">bus or a train? Cool what ever it is.</td>', 'bus or a train? Cool what ever it is.', '2002-06-10 18:40:00.000000', NULL, 1),
(72012, 2323, 1313, '<td valign="top">Since your picture shows a big number 2 that is what I gave you :)</td>', 'Since your picture shows a big number 2 that is what I gave you :)', '2002-06-10 21:53:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(72013, 2323, 714, '<td valign="top">creativety 3    interesting  2   focus 5    framing  4   = 4</td>', 'creativety 3    interesting  2   focus 5    framing  4   = 4', '2002-06-11 01:30:00.000000', NULL, 1),
(72014, 2323, 1897, '<td valign="top">thsi composition is lacking, the faces should not be cut off.  At least is it showing some creative thinking.</td>', 'thsi composition is lacking, the faces should not be cut off.  At least is it showing some creative thinking.', '2002-06-11 02:14:00.000000', NULL, 1),
(72015, 2323, 1041, '<td valign="top">Good idea.  It feels as if the people in the window should be the focal point for my attention, but the 2 keeps drawing my eyes away, it also doesn''t help that the girl is cut off.  Your horizon also isn''t quite level (parallel lines in bottom right).</td>', 'Good idea.  It feels as if the people in the window should be the focal point for my attention, but the 2 keeps drawing my eyes away, it also doesn''t help that the girl is cut off.  Your horizon also isn''t quite level (parallel lines in bottom right).', '2002-06-12 13:22:00.000000', NULL, 1),
(72016, 2323, 1054, '<td valign="top">Metallic bus?  We call ''em trains here.</td>', 'Metallic bus?  We call ''em trains here.', '2002-06-12 22:09:00.000000', NULL, 1),
(72017, 2323, 1379, '<td valign="top">The number 2 with two visible passengers...  Very nice coincidence!  I like the expression on the matron''s face in the window.  She looks so fleshy and human against the steely rail car.</td>', 'The number 2 with two visible passengers...  Very nice coincidence!  I like the expression on the matron''s face in the window.  She looks so fleshy and human against the steely rail car.', '2002-06-12 22:20:00.000000', NULL, 1),
(72018, 2323, 472, '<td valign="top">cool.  a little fuzzy.  some barrel distortion apparent UR.  horizon also a bit sloped, gives a sloppy feel.</td>', 'cool.  a little fuzzy.  some barrel distortion apparent UR.  horizon also a bit sloped, gives a sloppy feel.', '2002-06-13 11:07:00.000000', NULL, 1),
(72019, 2323, 1042, '<td valign="top">Maybe I just have a fascination with the number 2, but I like this shot.  I like the way it''s cropped and the people sitting in the window make it. It''s really a good subject..the lines..the metallic color, even the reflection in the glass. It''s just cool.</td>', 'Maybe I just have a fascination with the number 2, but I like this shot.  I like the way it''s cropped and the people sitting in the window make it. It''s really a good subject..the lines..the metallic color, even the reflection in the glass. It''s just cool.', '2002-06-13 13:50:00.000000', NULL, 1),
(72020, 2323, 1037, '<td valign="top">Interesting... lots of metallic texturing and structure to look at. One of  those things you don''t look at that way until someone takes a photo and forces you to stop and examine it for a while.</td>', 'Interesting... lots of metallic texturing and structure to look at. One of  those things you don''t look at that way until someone takes a photo and forces you to stop and examine it for a while.', '2002-06-16 03:17:00.000000', NULL, 1),
(72021, 2323, 1, '<td valign="top">This looks like a train to me.  No road is visible.</td>', 'This looks like a train to me.  No road is visible.', '2002-06-16 13:05:00.000000', NULL, 1),
(72022, 2324, 1569, '<td valign="top">Nice trolley pix!!</td>', 'Nice trolley pix!!', '2002-06-10 13:57:00.000000', NULL, 1),
(72023, 2324, 573, '<td valign="top">Nice picture, I like the brilliant colors.  Could a polarizing filter been used to reduce the distracting reflections from the window?</td>', 'Nice picture, I like the brilliant colors.  Could a polarizing filter been used to reduce the distracting reflections from the window?', '2002-06-10 14:44:00.000000', NULL, 1),
(72024, 2324, 327, '<td valign="top">Nice color, nice composition.</td>', 'Nice color, nice composition.', '2002-06-10 18:20:00.000000', NULL, 1),
(72025, 2324, 1005, '<td valign="top">Great photo.  A person or two might have added a little "interest", but still a great shot.  Nothing to critique (except for the previous NIT)  (I know, how about a child riding on the cowsweeper!)  Photo 10 Creativity 6 Road 9 total 8</td>', 'Great photo.  A person or two might have added a little "interest", but still a great shot.  Nothing to critique (except for the previous NIT)  (I know, how about a child riding on the cowsweeper!)  Photo 10 Creativity 6 Road 9 total 8', '2002-06-10 21:04:00.000000', NULL, 1),
(72026, 2324, 1313, '<td valign="top">Nice picture, good coloer and sharp.</td>', 'Nice picture, good coloer and sharp.', '2002-06-10 21:26:00.000000', NULL, 1),
(72027, 2324, 1944, '<td valign="top">As far as technique goes, a great photo. I like the subject also. My only complaint would be the verticals (especially on the left where they should be) aren''t.</td>', 'As far as technique goes, a great photo. I like the subject also. My only complaint would be the verticals (especially on the left where they should be) aren''t.', '2002-06-10 23:19:00.000000', NULL, 1),
(72028, 2324, 714, '<td valign="top">creativety 6    interesting  6  focus 9   framing 8   = 7</td>', 'creativety 6    interesting  6  focus 9   framing 8   = 7', '2002-06-11 01:35:00.000000', NULL, 1),
(72029, 2324, 772, '<td valign="top">The color and clarity in this photo are very nice... I also like the reflections in the window glass on this car.  I don''t know what it is about this yellow color, but I really like it.  Great shot!</td>', 'The color and clarity in this photo are very nice... I also like the reflections in the window glass on this car.  I don''t know what it is about this yellow color, but I really like it.  Great shot!', '2002-06-11 15:39:00.000000', NULL, 1),
(72030, 2324, 89, '<td valign="top">Left side needs more contrasting background, otherwise a nice shot.</td>', 'Left side needs more contrasting background, otherwise a nice shot.', '2002-06-11 16:12:00.000000', NULL, 1),
(72031, 2324, 2111, '<td valign="top">What number is it?</td>', 'What number is it?', '2002-06-11 17:00:00.000000', NULL, 1),
(72032, 2324, 1, '<td valign="top">Looks pretty much like a snap shot.</td>', 'Looks pretty much like a snap shot.', '2002-06-12 12:16:00.000000', NULL, 1),
(72033, 2324, 1054, '<td valign="top">Good composition.</td>', 'Good composition.', '2002-06-13 01:02:00.000000', NULL, 1),
(72034, 2324, 472, '<td valign="top">needs to be rotated 1 or 2 deg clockwise.  a nice shot, overall</td>', 'needs to be rotated 1 or 2 deg clockwise.  a nice shot, overall', '2002-06-13 11:25:00.000000', NULL, 1),
(72035, 2324, 1041, '<td valign="top">That building in the background is about to fall over to the left!  I like the colors of the trolley and how it fills the frame though.</td>', 'That building in the background is about to fall over to the left!  I like the colors of the trolley and how it fills the frame though.', '2002-06-13 11:57:00.000000', NULL, 1),
(72036, 2324, 637, '<td valign="top">OK angle, ok colors, ok lighting... subject could be more interesting with people or more scenery</td>', 'OK angle, ok colors, ok lighting... subject could be more interesting with people or more scenery', '2002-06-14 14:04:00.000000', NULL, 1),
(72037, 2324, 2000, '<td valign="top">nicely framed, and i like the reflections</td>', 'nicely framed, and i like the reflections', '2002-06-16 23:01:00.000000', NULL, 1),
(72038, 2325, 1829, '<td valign="top">LOL - Great shot.  Ummm by the way, where did you park your car when taking this picture?</td>', 'LOL - Great shot.  Ummm by the way, where did you park your car when taking this picture?', '2002-06-10 01:45:00.000000', NULL, 1),
(72039, 2325, 1344, '<td valign="top">wtf is the deal dude?  Gotta show ur naked beer belly in every pic or what?  bleh!</td>', 'wtf is the deal dude?  Gotta show ur naked beer belly in every pic or what?  bleh!', '2002-06-10 03:11:00.000000', NULL, 1),
(72040, 2325, 1360, '<td valign="top">Put</td>', 'Put', '2002-06-10 04:44:00.000000', NULL, 1),
(72041, 2325, 142, '<td valign="top">I could say something but I''m afraid I would regret it later.  Let''s just say I''m not impressed.</td>', 'I could say something but I''m afraid I would regret it later.  Let''s just say I''m not impressed.', '2002-06-10 09:36:00.000000', NULL, 1),
(72042, 2325, 1041, '<td valign="top">Not sure about the anonymity aspect of the photo, Mr. Jim.  Other than that, it looks very much like a snapshot.  You have a street sign growing out of your shoulder, shadows on your neck, and you are right in the middle of the shot.  Positioning towards one side of the shot and giving more visibility to the cars would''ve helped.</td>', 'Not sure about the anonymity aspect of the photo, Mr. Jim.  Other than that, it looks very much like a snapshot.  You have a street sign growing out of your shoulder, shadows on your neck, and you are right in the middle of the shot.  Positioning towards one side of the shot and giving more visibility to the cars would''ve helped.', '2002-06-10 13:08:00.000000', NULL, 1),
(72043, 2325, 573, '<td valign="top">I wouldn''t pick him up, but he is deffinatly ''On The Road''.</td>', 'I wouldn''t pick him up, but he is deffinatly ''On The Road''.', '2002-06-10 13:36:00.000000', NULL, 1),
(72044, 2325, 203, '<td valign="top">If I ever dressed like that I would hope a loved one would lock me in my room.</td>', 'If I ever dressed like that I would hope a loved one would lock me in my room.', '2002-06-10 14:58:00.000000', NULL, 1),
(72045, 2325, 772, '<td valign="top">Dude!</td>', 'Dude!', '2002-06-10 15:04:00.000000', NULL, 1),
(72046, 2325, 811, '<td valign="top">I''m glad  he''s leaning, that keeps the pole from coming straight out of his head.  I bet ya''ll got some strange looks. :-)  It''s a little flat to me, and I think a different angle would''ve made a more effective picture.  Having said that, dpc is great, but not worth getting run over for.  Did you try experimenting by cropping it so that he was not in the exact middle?</td>', 'I''m glad  he''s leaning, that keeps the pole from coming straight out of his head.  I bet ya''ll got some strange looks. :-)  It''s a little flat to me, and I think a different angle would''ve made a more effective picture.  Having said that, dpc is great, but not worth getting run over for.  Did you try experimenting by cropping it so that he was not in the exact middle?', '2002-06-10 18:08:00.000000', NULL, 1),
(72047, 2325, 1054, '<td valign="top">The noonday sun makes this photo look very flat.  Also, the man and sign make a line that divides the photo down the middle... Perhaps this would have been better-composed if you lined him up along the left third?</td>', 'The noonday sun makes this photo look very flat.  Also, the man and sign make a line that divides the photo down the middle... Perhaps this would have been better-composed if you lined him up along the left third?', '2002-06-10 18:20:00.000000', NULL, 1),
(72048, 2325, 327, '<td valign="top">Husky but friendly face....hum, like Ted Bundy? &amp;lt;lol&amp;gt; Great, creativity.</td>', 'Husky but friendly face....hum, like Ted Bundy? &lt;lol&gt; Great, creativity.', '2002-06-10 18:21:00.000000', NULL, 1),
(72049, 2325, 387, '<td valign="top">This is not the "Mr. Jim Exhibition Site". Please take interesting photos that don''t involve YOU.</td>', 'This is not the "Mr. Jim Exhibition Site". Please take interesting photos that don''t involve YOU.', '2002-06-10 20:27:00.000000', NULL, 1),
(72050, 2325, 1759, '<td valign="top">How much did you have to pay this guy? Interesting shot that might have been improved by composing the subject off-center. You also might want to use fill flash to counter the harsh sun light and lessen the shadow under his face.</td>', 'How much did you have to pay this guy? Interesting shot that might have been improved by composing the subject off-center. You also might want to use fill flash to counter the harsh sun light and lessen the shadow under his face.', '2002-06-10 20:57:00.000000', NULL, 1),
(72051, 2325, 737, '<td valign="top">And the point is? I''ve yet to see a bare chested hitch hiker.</td>', 'And the point is? I''ve yet to see a bare chested hitch hiker.', '2002-06-10 22:17:00.000000', NULL, 1),
(72052, 2325, 671, '<td valign="top">too much pink.</td>', 'too much pink.', '2002-06-10 22:48:00.000000', NULL, 1),
(72053, 2325, 554, '<td valign="top">nobody gonna pick you up standin there fella.   get outta the middle of the road .      besides, you too ugly</td>', 'nobody gonna pick you up standin there fella.   get outta the middle of the road .      besides, you too ugly', '2002-06-10 23:24:00.000000', NULL, 1),
(72054, 2325, 1907, '<td valign="top">i recall "me shaving" from the last challenge...</td>', 'i recall "me shaving" from the last challenge...', '2002-06-11 04:54:00.000000', NULL, 1),
(72055, 2325, 1446, '<td valign="top">It meets the challenge.  Certainly see the road.  Not an amazing photograph though.  It actually had potential, despite the comments I suspect you are getting, but the signpost "comming out of the subjects back" is a major distraction. Also, I dont know if you have ever looked at a hitch-hikers face, but they seldom looks quite so happy.  So you lost some reality points too.</td>', 'It meets the challenge.  Certainly see the road.  Not an amazing photograph though.  It actually had potential, despite the comments I suspect you are getting, but the signpost "comming out of the subjects back" is a major distraction. Also, I dont know if you have ever looked at a hitch-hikers face, but they seldom looks quite so happy.  So you lost some reality points too.', '2002-06-11 10:40:00.000000', NULL, 1),
(72056, 2325, 1882, '<td valign="top">oh gawd.  is this the same fat guy who was shaving in the last challenge?</td>', 'oh gawd.  is this the same fat guy who was shaving in the last challenge?', '2002-06-11 12:35:00.000000', NULL, 1),
(72057, 2325, 714, '<td valign="top">creativety 7 interesting 1 focus 5 framing 7 =5</td>', 'creativety 7 interesting 1 focus 5 framing 7 =5', '2002-06-11 14:41:00.000000', NULL, 1),
(72058, 2325, 121, '<td valign="top">I think he could be waiting for some considerable time.</td>', 'I think he could be waiting for some considerable time.', '2002-06-11 17:02:00.000000', NULL, 1),
(72059, 2325, 1005, '<td valign="top">Not my choice for topless, but I''m a guy!  Great photo, good humor,  good focus/framing/color/etc.<br/>Photo 9 Creativity (did you ask him to do this?) 7 Road 8 total 8</td>', 'Not my choice for topless, but I''m a guy!  Great photo, good humor,  good focus/framing/color/etc.Photo 9 Creativity (did you ask him to do this?) 7 Road 8 total 8', '2002-06-11 20:53:00.000000', NULL, 1),
(72060, 2325, 1042, '<td valign="top">are we going to be forced to look at you every week? Do you  have another subject, you think?</td>', 'are we going to be forced to look at you every week? Do you  have another subject, you think?', '2002-06-11 23:49:00.000000', NULL, 1),
(72061, 2325, 1877, '<td valign="top">Well... you were brave.. but. um.. nah.</td>', 'Well... you were brave.. but. um.. nah.', '2002-06-12 02:40:00.000000', NULL, 1),
(72062, 2325, 1031, '<td valign="top">The advantage of hitchhiking from the median strip is you can catch a ride in either direction.</td>', 'The advantage of hitchhiking from the median strip is you can catch a ride in either direction.', '2002-06-12 03:56:00.000000', NULL, 1),
(72063, 2325, 1897, '<td valign="top">Put a damn shirt one</td>', 'Put a damn shirt one', '2002-06-14 01:26:00.000000', NULL, 1),
(72064, 2325, 2203, '<td valign="top">I really like this picture..Its got an all American feel to it!</td>', 'I really like this picture..Its got an all American feel to it!', '2002-06-14 01:37:00.000000', NULL, 1),
(72065, 2325, 2047, '<td valign="top">just nasty!</td>', 'just nasty!', '2002-06-15 00:11:00.000000', NULL, 1),
