(72079, 2326, 1031, '<td valign="top">If there''s not too much traffic overhead it looks like a cool place to play music too...</td>', 'If there''s not too much traffic overhead it looks like a cool place to play music too...', '2002-06-13 02:13:00.000000', NULL, 1),
(72080, 2326, 1041, '<td valign="top">I personally would find this shot a little more interesting with something on the road to hold my interest, but the placement of the tunnel and the road leading into the distance is well done.</td>', 'I personally would find this shot a little more interesting with something on the road to hold my interest, but the placement of the tunnel and the road leading into the distance is well done.', '2002-06-14 12:13:00.000000', NULL, 1),
(72081, 2326, 637, '<td valign="top">Very well done: perspective, colors and shadow.</td>', 'Very well done: perspective, colors and shadow.', '2002-06-15 02:46:00.000000', NULL, 1),
