INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(72213, 2331, 1066, '<td valign="top">Thanks for all th comments folks.<br/><br/>A little about the photo.<br/><br/>Ever drive along th highway and see that heat blur rising off the pavement?  As a kid we called that the Asphale Mirage and thus my name :-)<br/><br/>When I think of mirages I think desert/camels etc.  so..I found a cool shot of a camel and a stock desert scene with a road in it and put them in photoshop and made a composite image.  I knew in advance I needed a genreic blu sky so I leveld the composite to give me a dsert with a blue sky.<br/><br/>Then I took my compostie image and placed it in front of a mirror board that has texture to it so I got a mirror image that was slightly distorted.  I then took that image into photoshop, gave it a slight water blur and printed onto photo card stock.<br/><br/>The idea of tearing the top of the art came to me on the drive to the location to shoot.  I saw the clouds overhead and wanted to blend the photo into the real clouds.  I tried to get some nice white edging to show on the card stock to give a cloud edge effect.<br/><br/>After gettng to my location ( a nice quite school parking lot ) I arranged my elements.  The knife is an artist tool for cutting in straight lines to paintings.  I figured some of the voters might not have painting experience and not know why I used a knife.  Also the refldctive surface of the knife caught the clouds too!<br/><br/>I actually used more paint than I wanted and I didn''t get to really blend the paint into the road stripe of the photo as well as I wanted.  Trying to do a studio style shot in the middle of a real road surface was a challenge in itself!<br/><br/>I can imagine the looks I got of me laying in the middle of the road wating for the clouds to move overhead into just the right postion. :-)</td>', 'Thanks for all th comments folks.A little about the photo.Ever drive along th highway and see that heat blur rising off the pavement?  As a kid we called that the Asphale Mirage and thus my name :-)When I think of mirages I think desert/camels etc.  so..I found a cool shot of a camel and a stock desert scene with a road in it and put them in photoshop and made a composite image.  I knew in advance I needed a genreic blu sky so I leveld the composite to give me a dsert with a blue sky.Then I took my compostie image and placed it in front of a mirror board that has texture to it so I got a mirror image that was slightly distorted.  I then took that image into photoshop, gave it a slight water blur and printed onto photo card stock.The idea of tearing the top of the art came to me on the drive to the location to shoot.  I saw the clouds overhead and wanted to blend the photo into the real clouds.  I tried to get some nice white edging to show on the card stock to give a cloud edge effect.After gettng to my location ( a nice quite school parking lot ) I arranged my elements.  The knife is an artist tool for cutting in straight lines to paintings.  I figured some of the voters might not have painting experience and not know why I used a knife.  Also the refldctive surface of the knife caught the clouds too!I actually used more paint than I wanted and I didn''t get to really blend the paint into the road stripe of the photo as well as I wanted.  Trying to do a studio style shot in the middle of a real road surface was a challenge in itself!I can imagine the looks I got of me laying in the middle of the road wating for the clouds to move overhead into just the right postion. :-)', '2002-06-17 12:04:00.000000', NULL, 0),
(72214, 2331, 472, '<td valign="top">yup, i was right. your signature creative flair :) .. kudos to you-doe: i love it.</td>', 'yup, i was right. your signature creative flair :) .. kudos to you-doe: i love it.', '2002-06-17 12:39:00.000000', NULL, 0),
(72215, 2331, 772, '<td valign="top">Hokie, I *do* like your work quite a bit... As I look back through your submissions, I can see quite clearly that yours have been some of my highest rated shots in the past... This particular photo sent me spinning though :)</td>', 'Hokie, I *do* like your work quite a bit... As I look back through your submissions, I can see quite clearly that yours have been some of my highest rated shots in the past... This particular photo sent me spinning though :)', '2002-06-17 17:32:00.000000', NULL, 0),
(72216, 2332, 1226, '<td valign="top">Very nice shot. I am curous as to where this is... i look forward to the results so we can all find out.</td>', 'Very nice shot. I am curous as to where this is... i look forward to the results so we can all find out.', '2002-06-10 12:13:00.000000', NULL, 1),
(72217, 2332, 1856, '<td valign="top">beautiful setting.  I love the sunlight on the fence...but don''t like how it''s blurring the horizon.</td>', 'beautiful setting.  I love the sunlight on the fence...but don''t like how it''s blurring the horizon.', '2002-06-10 13:00:00.000000', NULL, 1),
(72218, 2332, 1528, '<td valign="top">i really like this<br/>tho, the ''pinks'' in the road and oranges on the fence aren''t very self-explanatory and leave me wondering if they are the sunset, discoloration, or what.  so a little distracting i guess.<br/>but nice subject and composition</td>', 'i really like thistho, the ''pinks'' in the road and oranges on the fence aren''t very self-explanatory and leave me wondering if they are the sunset, discoloration, or what.  so a little distracting i guess.but nice subject and composition', '2002-06-10 15:45:00.000000', NULL, 1),
(72219, 2332, 885, '<td valign="top">Hmm, what''s that red light from?</td>', 'Hmm, what''s that red light from?', '2002-06-10 16:02:00.000000', NULL, 1),
(72220, 2332, 1944, '<td valign="top">Beautiful use of light! I love the mood.</td>', 'Beautiful use of light! I love the mood.', '2002-06-10 16:28:00.000000', NULL, 1),
(72221, 2332, 327, '<td valign="top">Lots of magenta..was that the color of the sky or the sun? Cool shot.</td>', 'Lots of magenta..was that the color of the sky or the sun? Cool shot.', '2002-06-10 18:26:00.000000', NULL, 1),
(72222, 2332, 1313, '<td valign="top">Not very creative but a good shot.</td>', 'Not very creative but a good shot.', '2002-06-10 21:10:00.000000', NULL, 1),
(72223, 2332, 737, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2002-06-10 22:06:00.000000', NULL, 1),
(72224, 2332, 2093, '<td valign="top">Nice area but the house is a bit dark. I would think that the details need to be a bit brighter</td>', 'Nice area but the house is a bit dark. I would think that the details need to be a bit brighter', '2002-06-11 10:00:00.000000', NULL, 1),
(72225, 2332, 1882, '<td valign="top">Pretty photo.  Interesting building covered with the green in the background.  Look like there is no back to the structure; would like to know more about it.</td>', 'Pretty photo.  Interesting building covered with the green in the background.  Look like there is no back to the structure; would like to know more about it.', '2002-06-11 12:14:00.000000', NULL, 1),
(72226, 2332, 1005, '<td valign="top">a beautiful photo.  The sunset in the driveway shows up really interestingly (extra red), but the sky is almost blank (hint of red/purple).  This photo looks "natural", so I am guessing you didn''t touch up the color, maybe it would have helped (just a touch more red).    I don''t know what else to suggest, overall, this is a very nice shot, but I keep looking at the washed out sky and wondering, was it THAT hazy?  (maybe)<br/>Photo 9 Creativity 7 Road 8 total 8</td>', 'a beautiful photo.  The sunset in the driveway shows up really interestingly (extra red), but the sky is almost blank (hint of red/purple).  This photo looks "natural", so I am guessing you didn''t touch up the color, maybe it would have helped (just a touch more red).    I don''t know what else to suggest, overall, this is a very nice shot, but I keep looking at the washed out sky and wondering, was it THAT hazy?  (maybe)Photo 9 Creativity 7 Road 8 total 8', '2002-06-11 19:13:00.000000', NULL, 1),
(72227, 2332, 1, '<td valign="top">Very strange lighting indeed.  The coloration on the gravel/fence are a little out of place it seems with all the greens and browns.</td>', 'Very strange lighting indeed.  The coloration on the gravel/fence are a little out of place it seems with all the greens and browns.', '2002-06-12 12:08:00.000000', NULL, 1),
(72228, 2332, 772, '<td valign="top">Nice landscape shot :)</td>', 'Nice landscape shot :)', '2002-06-12 18:23:00.000000', NULL, 1),
