(72236, 2332, 1122, '<td valign="top">I love this picture!<br/>Was it dawn or sunset?</td>', 'I love this picture!Was it dawn or sunset?', '2002-06-14 16:06:00.000000', NULL, 1),
(72237, 2332, 2210, '<td valign="top">Nice curves. Would like to have seen the picture of the barn. very interesting</td>', 'Nice curves. Would like to have seen the picture of the barn. very interesting', '2002-06-14 16:54:00.000000', NULL, 1),
(72238, 2332, 1037, '<td valign="top">Something about the composition of this photo is a little bit awkward, with that building on the left. The lighting and colours are very nice though.</td>', 'Something about the composition of this photo is a little bit awkward, with that building on the left. The lighting and colours are very nice though.', '2002-06-16 10:11:00.000000', NULL, 1),
(72239, 2332, 1041, '<td valign="top">Thanks all for the kind votes.  This photo did much better than I expected (and in my mind than it deserved, but I''m certainly not complaining).  I''m especially thrilled that this is my first no 1s photo! :)</td>', 'Thanks all for the kind votes.  This photo did much better than I expected (and in my mind than it deserved, but I''m certainly not complaining).  I''m especially thrilled that this is my first no 1s photo! :)', '2002-06-17 15:34:00.000000', NULL, 0),
