(72241, 2333, 205, '<td valign="top">I hope people don''t dog on the tilted composition like they did on one of mine.</td>', 'I hope people don''t dog on the tilted composition like they did on one of mine.', '2002-06-10 06:00:00.000000', NULL, 1),
(72242, 2333, 1755, '<td valign="top">Ísland...</td>', 'Ísland...', '2002-06-10 10:16:00.000000', NULL, 1),
(72243, 2333, 1859, '<td valign="top">Not sure if that blurry blue thing on the left is a speeding car, bike or what, but whatever it is, it works for me.  Very cool shot.</td>', 'Not sure if that blurry blue thing on the left is a speeding car, bike or what, but whatever it is, it works for me.  Very cool shot.', '2002-06-10 12:33:00.000000', NULL, 1),
(72244, 2333, 656, '<td valign="top">as the person who entered the ''other'' stop sign picture I don''t know whether to mark up your obviously great intellect, creativity and vision, or mark down the only competition :)<br/><br/>The tilt works well and I like the juxtaposition of the car that obviously isn''t stopped.  Colours/ light is a bit flat though.</td>', 'as the person who entered the ''other'' stop sign picture I don''t know whether to mark up your obviously great intellect, creativity and vision, or mark down the only competition :)The tilt works well and I like the juxtaposition of the car that obviously isn''t stopped.  Colours/ light is a bit flat though.', '2002-06-10 13:22:00.000000', NULL, 1),
(72245, 2333, 885, '<td valign="top">I like the angle and the blue streak.  You are almost successful in getting those power lines to disappear :-)  I like the fact that the car almost is the same color as the mountains in the background, and the red is such a striking contrast to that.  Good job.</td>', 'I like the angle and the blue streak.  You are almost successful in getting those power lines to disappear :-)  I like the fact that the car almost is the same color as the mountains in the background, and the red is such a striking contrast to that.  Good job.', '2002-06-10 14:26:00.000000', NULL, 1),
(72246, 2333, 1944, '<td valign="top">This works well. They tried to teach me the ''11 degree'' rule, that it''s assumed to be purposful if it''s more than 11 degrees off plumb:). Nice picture.</td>', 'This works well. They tried to teach me the ''11 degree'' rule, that it''s assumed to be purposful if it''s more than 11 degrees off plumb:). Nice picture.', '2002-06-10 18:27:00.000000', NULL, 1),
(72247, 2333, 327, '<td valign="top">Halt! Fun shot, good work, done well.</td>', 'Halt! Fun shot, good work, done well.', '2002-06-10 18:43:00.000000', NULL, 1),
