(72256, 2333, 472, '<td valign="top">this tilted horizon adds to the feeling of speed. the movement juxtaposed with the stop sign is a great statement. one of th ebetter pics in the challenge.</td>', 'this tilted horizon adds to the feeling of speed. the movement juxtaposed with the stop sign is a great statement. one of th ebetter pics in the challenge.', '2002-06-13 11:09:00.000000', NULL, 1),
(72257, 2333, 1042, '<td valign="top">I love what the photo says to me. The speeding car flying past is just a wonderful detail. The angle is great. I love the colors....great.</td>', 'I love what the photo says to me. The speeding car flying past is just a wonderful detail. The angle is great. I love the colors....great.', '2002-06-13 14:00:00.000000', NULL, 1),
(72258, 2333, 772, '<td valign="top">I like the tilted perspective of this photo.. i believe that a slightly shorter exposure to highlight the passing car, but still enough to allow the blur would have been nice as well... great work!</td>', 'I like the tilted perspective of this photo.. i believe that a slightly shorter exposure to highlight the passing car, but still enough to allow the blur would have been nice as well... great work!', '2002-06-13 16:00:00.000000', NULL, 1),
(72259, 2333, 811, '<td valign="top">Very good (and ironic) use of blur.</td>', 'Very good (and ironic) use of blur.', '2002-06-13 17:24:00.000000', NULL, 1),
(72260, 2333, 208, '<td valign="top">Good idea! Not sure the angle is necessary, but overall a nice shot. You made the motion work here.</td>', 'Good idea! Not sure the angle is necessary, but overall a nice shot. You made the motion work here.', '2002-06-13 20:05:00.000000', NULL, 1),
(72261, 2333, 2109, '<td valign="top">smooth</td>', 'smooth', '2002-06-13 22:34:00.000000', NULL, 1),
(72262, 2333, 637, '<td valign="top">nice angle</td>', 'nice angle', '2002-06-14 14:03:00.000000', NULL, 1),
