(72389, 2341, 714, '<td valign="top">creativety 3    interesting 3   focus 6 framing 4  =  4</td>', 'creativety 3    interesting 3   focus 6 framing 4  =  4', '2002-06-11 11:24:00.000000', NULL, 1),
