(72392, 2341, 878, '<td valign="top">This would be a better shot if you wer up about 20 feet past the shadows.  The sky and colors give the shot a nice feel.  The shot is a bit too grainy and not sharply focused.</td>', 'This would be a better shot if you wer up about 20 feet past the shadows.  The sky and colors give the shot a nice feel.  The shot is a bit too grainy and not sharply focused.', '2002-06-11 17:37:00.000000', NULL, 1),
(72393, 2341, 1005, '<td valign="top">Very nice, thank you for including the car.  This is good enough to say, job well done, no critiques to offer, sorry.<br/>Photo 9 Creativity 7 Road 8 total 8</td>', 'Very nice, thank you for including the car.  This is good enough to say, job well done, no critiques to offer, sorry.Photo 9 Creativity 7 Road 8 total 8', '2002-06-11 20:26:00.000000', NULL, 1),
(72394, 2341, 1893, '<td valign="top">A little too much sky.</td>', 'A little too much sky.', '2002-06-12 10:32:00.000000', NULL, 1),
