(72398, 2341, 1037, '<td valign="top">Nice, peaceful landscape scene with late afternoon light and long shadows... but a bit dull. Needed to be rotated a bit, I think.</td>', 'Nice, peaceful landscape scene with late afternoon light and long shadows... but a bit dull. Needed to be rotated a bit, I think.', '2002-06-14 06:15:00.000000', NULL, 1),
(72399, 2341, 748, '<td valign="top">With the subject being "on the road", there is too much sky.  It would have been been better to have lowered your camera angle and pushed the sky nearer the top of the frame.</td>', 'With the subject being "on the road", there is too much sky.  It would have been been better to have lowered your camera angle and pushed the sky nearer the top of the frame.', '2002-06-14 07:20:00.000000', NULL, 1),
