(72406, 2342, 616, '<td valign="top">wow, That was a great idea!</td>', 'wow, That was a great idea!', '2002-06-10 20:52:00.000000', NULL, 1),
(72407, 2342, 1005, '<td valign="top">Really cool idea and very well executed!  (red car, eh?)  I must be in the "good" section, this is another potential winner!)  No suggestions, this is great work!  <br/>Photo 10 Creativity 10++ (best) Road 10 total 10 (is there a higher score, please?)</td>', 'Really cool idea and very well executed!  (red car, eh?)  I must be in the "good" section, this is another potential winner!)  No suggestions, this is great work!  Photo 10 Creativity 10++ (best) Road 10 total 10 (is there a higher score, please?)', '2002-06-10 21:02:00.000000', NULL, 1),
(72408, 2342, 1759, '<td valign="top">I like this shot! It is the most interesting auto shot I''ve seen so far. Good effects, exposure, and contrast.</td>', 'I like this shot! It is the most interesting auto shot I''ve seen so far. Good effects, exposure, and contrast.', '2002-06-10 22:52:00.000000', NULL, 1),
(72409, 2342, 1877, '<td valign="top">I thought this was the rearview mirror .. but now i see it as sunglasses..  A good idea but i think its a bit dark and that the rv is distracting. Maybe if there was something else dynamic in the view?</td>', 'I thought this was the rearview mirror .. but now i see it as sunglasses..  A good idea but i think its a bit dark and that the rv is distracting. Maybe if there was something else dynamic in the view?', '2002-06-12 02:38:00.000000', NULL, 1),
(72410, 2342, 1658, '<td valign="top">I like the creativity of this shot a lot.  I would like to have a sharper focus on the reflective surface, but this is a very minor nit.  I really like this shot.  Good job!</td>', 'I like the creativity of this shot a lot.  I would like to have a sharper focus on the reflective surface, but this is a very minor nit.  I really like this shot.  Good job!', '2002-06-12 12:20:00.000000', NULL, 1),
(72411, 2342, 472, '<td valign="top">i like the curvature of the reflection.  it helps that i dont really know what im seeing.  but the shot is really crisp in the mirror.</td>', 'i like the curvature of the reflection.  it helps that i dont really know what im seeing.  but the shot is really crisp in the mirror.', '2002-06-12 18:08:00.000000', NULL, 1),
