INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(72413, 2342, 1031, '<td valign="top">I''d like to see the setup to get this angle...</td>', 'I''d like to see the setup to get this angle...', '2002-06-13 00:36:00.000000', NULL, 1),
(72414, 2342, 1897, '<td valign="top">Looks like someone needs a pore cleaning</td>', 'Looks like someone needs a pore cleaning', '2002-06-14 01:27:00.000000', NULL, 1),
(72415, 2342, 1041, '<td valign="top">Unique perspective.  I wish I was in that RV going on vacation . . .</td>', 'Unique perspective.  I wish I was in that RV going on vacation . . .', '2002-06-14 13:19:00.000000', NULL, 1),
(72416, 2342, 1, '<td valign="top">Nice shot, the colors are great.  Good framing too.</td>', 'Nice shot, the colors are great.  Good framing too.', '2002-06-17 00:24:00.000000', NULL, 1),
(72417, 2343, 1, '<td valign="top">Funny idea, I think you could use some work on framing... like not chopping off the mirror, and using less dash board.</td>', 'Funny idea, I think you could use some work on framing... like not chopping off the mirror, and using less dash board.', '2002-06-10 10:08:00.000000', NULL, 1),
(72418, 2343, 1024, '<td valign="top">wow, where was this taken....... that is really "off the road" to most of us drivers.</td>', 'wow, where was this taken....... that is really "off the road" to most of us drivers.', '2002-06-10 17:34:00.000000', NULL, 1),
(72419, 2343, 327, '<td valign="top">Wow, off roading! lol Fun shot.</td>', 'Wow, off roading! lol Fun shot.', '2002-06-10 18:44:00.000000', NULL, 1),
(72420, 2343, 1759, '<td valign="top">I really like this idea, and it looks like a good spot for the shot. However, though I can see that you are trying to bring the viewer into the car, the over the shoulder view gives me a crowded feeling and takes my attention away from the view out the window. Did you try this shot more toward the front seat or maybe over the hood? I gave good marks for an original idea.</td>', 'I really like this idea, and it looks like a good spot for the shot. However, though I can see that you are trying to bring the viewer into the car, the over the shoulder view gives me a crowded feeling and takes my attention away from the view out the window. Did you try this shot more toward the front seat or maybe over the hood? I gave good marks for an original idea.', '2002-06-10 21:19:00.000000', NULL, 1),
(72421, 2343, 1944, '<td valign="top">It is if you want it to be.</td>', 'It is if you want it to be.', '2002-06-10 23:31:00.000000', NULL, 1),
(72422, 2343, 714, '<td valign="top">creativety 6     interesting 3    focus  8  framing  6    =   6</td>', 'creativety 6     interesting 3    focus  8  framing  6    =   6', '2002-06-11 11:20:00.000000', NULL, 1),
(72423, 2343, 573, '<td valign="top">Yes, yes it is.  Just keep going forward.  I would prefer to see more turough the window and less of the dashboard. good photograph.</td>', 'Yes, yes it is.  Just keep going forward.  I would prefer to see more turough the window and less of the dashboard. good photograph.', '2002-06-11 12:09:00.000000', NULL, 1),
(72424, 2343, 1446, '<td valign="top">This photograph feels cut in 2 by the horizontal dash-board.</td>', 'This photograph feels cut in 2 by the horizontal dash-board.', '2002-06-11 13:12:00.000000', NULL, 1),
(72425, 2343, 772, '<td valign="top">On the road or not, the overall interest leve on this photo is not very appealing to me...</td>', 'On the road or not, the overall interest leve on this photo is not very appealing to me...', '2002-06-12 18:01:00.000000', NULL, 1),
(72426, 2343, 1054, '<td valign="top">Creative, but the cropping/flaming makes the whole thing feel off-balance to me.</td>', 'Creative, but the cropping/flaming makes the whole thing feel off-balance to me.', '2002-06-12 21:49:00.000000', NULL, 1),
(72427, 2343, 472, '<td valign="top">ok shot, although subject matter is a bit static (ie not particularly interesting).</td>', 'ok shot, although subject matter is a bit static (ie not particularly interesting).', '2002-06-13 11:10:00.000000', NULL, 1),
(72428, 2343, 811, '<td valign="top">Hmmmm, hope that''s four-wheel drive ;-)  I like the way it''s framed, giving me that back-seat driver feel, but all of the colors are kinda drab.  Maybe if the jacket/shirt had been a bright color, or any color besides gray, it would have livened it up a bit.</td>', 'Hmmmm, hope that''s four-wheel drive ;-)  I like the way it''s framed, giving me that back-seat driver feel, but all of the colors are kinda drab.  Maybe if the jacket/shirt had been a bright color, or any color besides gray, it would have livened it up a bit.', '2002-06-13 17:27:00.000000', NULL, 1),
