(72739, 2368, 573, '<td valign="top">I put this picture in my top ten because it''s perfict for sepia print.</td>', 'I put this picture in my top ten because it''s perfict for sepia print.', '2002-06-11 17:25:00.000000', NULL, 1),
(72740, 2368, 1005, '<td valign="top">Excellent use of Sepia!!!  Too bad you couldn''t have gotten a slightly higher view, or side or front view (my more favored vantage points), but no points deducted.  Good clarity of image, detail and framing.    Photo 9 Creativity 7 Road 8 total 8</td>', 'Excellent use of Sepia!!!  Too bad you couldn''t have gotten a slightly higher view, or side or front view (my more favored vantage points), but no points deducted.  Good clarity of image, detail and framing.    Photo 9 Creativity 7 Road 8 total 8', '2002-06-11 19:42:00.000000', NULL, 1),
(72741, 2368, 1519, '<td valign="top">This is very cute.  Like the coloring.  Does it look so grainy on purpose?  I like the effect, so high score! :)</td>', 'This is very cute.  Like the coloring.  Does it look so grainy on purpose?  I like the effect, so high score! :)', '2002-06-11 23:17:00.000000', NULL, 1),
