INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(72815, 2372, 1944, '<td valign="top">Captures the mood well. Well executed photograph.</td>', 'Captures the mood well. Well executed photograph.', '2002-06-11 21:29:00.000000', NULL, 1),
(72816, 2372, 1519, '<td valign="top">This turned out really cool.  I like the light focused on the person''s face and thumb.  Cool motion with the car.  almost looks like a rocket! Nice!</td>', 'This turned out really cool.  I like the light focused on the person''s face and thumb.  Cool motion with the car.  almost looks like a rocket! Nice!', '2002-06-11 23:25:00.000000', NULL, 1),
(72817, 2372, 2023, '<td valign="top">Very nice composition!</td>', 'Very nice composition!', '2002-06-12 12:25:00.000000', NULL, 1),
(72818, 2372, 772, '<td valign="top">I don''t really know why, but this photo is one of my 10s this week.  I think you did an excellent job with this long exposure.  You did a great job of keeping the hitchhiker in focus without blur.  I REALLY would like to see a little more back lighting in this photo.. there is enought there to highlight the hitchhiker''s back but I think that if the guitar case was accented a little more, there would be much more impact in this photo.  You really have to look twice to even notice that it''s there... Kudos on a fine job!</td>', 'I don''t really know why, but this photo is one of my 10s this week.  I think you did an excellent job with this long exposure.  You did a great job of keeping the hitchhiker in focus without blur.  I REALLY would like to see a little more back lighting in this photo.. there is enought there to highlight the hitchhiker''s back but I think that if the guitar case was accented a little more, there would be much more impact in this photo.  You really have to look twice to even notice that it''s there... Kudos on a fine job!', '2002-06-12 12:41:00.000000', NULL, 1),
(72819, 2372, 1054, '<td valign="top">Great shot, and I *LOVE* the title.</td>', 'Great shot, and I *LOVE* the title.', '2002-06-12 18:57:00.000000', NULL, 1),
(72820, 2372, 933, '<td valign="top">Nice photo.  Has a good feel to it.  Well composed.</td>', 'Nice photo.  Has a good feel to it.  Well composed.', '2002-06-13 01:29:00.000000', NULL, 1),
(72821, 2372, 1031, '<td valign="top">There''s that "mostly" qualifier again...</td>', 'There''s that "mostly" qualifier again...', '2002-06-13 02:31:00.000000', NULL, 1),
(72822, 2372, 1041, '<td valign="top">The more I look at this one, the more I like it.</td>', 'The more I look at this one, the more I like it.', '2002-06-13 10:37:00.000000', NULL, 1),
(72823, 2372, 27, '<td valign="top">how did you find a guy with a light sabre for a peenie?</td>', 'how did you find a guy with a light sabre for a peenie?', '2002-06-13 11:37:00.000000', NULL, 1),
(72824, 2372, 255, '<td valign="top">but where is his towel?!! cool picture--i think this is a very good reference to the book---that could totally be a spaceship!</td>', 'but where is his towel?!! cool picture--i think this is a very good reference to the book---that could totally be a spaceship!', '2002-06-13 17:25:00.000000', NULL, 1),
(72825, 2372, 1037, '<td valign="top">Excellent work. The sparks are a great effect, and light up the guy''s outline really nicely.</td>', 'Excellent work. The sparks are a great effect, and light up the guy''s outline really nicely.', '2002-06-14 06:07:00.000000', NULL, 1),
(72826, 2372, 1707, '<td valign="top">Cool effects!</td>', 'Cool effects!', '2002-06-14 12:31:00.000000', NULL, 1),
(72827, 2372, 1024, '<td valign="top">Nice use of blur to isolate your subject.</td>', 'Nice use of blur to isolate your subject.', '2002-06-14 14:49:00.000000', NULL, 1),
(72828, 2372, 2199, '<td valign="top">WOW!</td>', 'WOW!', '2002-06-14 23:41:00.000000', NULL, 1),
(72829, 2372, 47, '<td valign="top">hell yes.</td>', 'hell yes.', '2002-06-15 14:45:00.000000', NULL, 1),
(72830, 2372, 1831, '<td valign="top">Creative, I like "9"</td>', 'Creative, I like "9"', '2002-06-15 16:38:00.000000', NULL, 1),
(72831, 2372, 472, '<td valign="top">in the thumbnail, this looks like it is going to be something involving welding.  i find this to be a very interesting and arresting image.  Kudos to the model for keeping so still for the duration of the exposure.i''m trying to piece together what the repeating shape is under the beam of light.  i think if i can figure out the direction of travel of the vehicles, i will understand.  i would not pick this guy up unless Gandalf and Obi Wan were with me in the car.</td>', 'in the thumbnail, this looks like it is going to be something involving welding.  i find this to be a very interesting and arresting image.  Kudos to the model for keeping so still for the duration of the exposure.i''m trying to piece together what the repeating shape is under the beam of light.  i think if i can figure out the direction of travel of the vehicles, i will understand.  i would not pick this guy up unless Gandalf and Obi Wan were with me in the car.', '2002-06-15 22:51:00.000000', NULL, 1),
(72832, 2372, 2235, '<td valign="top">Good idea. Like fill flash for subject. Cars are a bit too blurred to help with concept  of title. Tough shot to get and combine. Well done</td>', 'Good idea. Like fill flash for subject. Cars are a bit too blurred to help with concept  of title. Tough shot to get and combine. Well done', '2002-06-16 09:28:00.000000', NULL, 1),
(72833, 2372, 1, '<td valign="top">Great shot, perfect exposure/framing/etc.  Very well done.</td>', 'Great shot, perfect exposure/framing/etc.  Very well done.', '2002-06-16 13:13:00.000000', NULL, 1),
(72834, 2372, 47, '<td valign="top">haha, i thought mousie took this picture. i suppose that''s a compliment on your end. i''m really just surprised.</td>', 'haha, i thought mousie took this picture. i suppose that''s a compliment on your end. i''m really just surprised.', '2002-06-17 07:53:00.000000', NULL, 0),
(72835, 2372, 885, '<td valign="top">Heh.  Well, I think that the white streaks are actually the builders'' light reflecting off the silver car, not the headlights.  I tried it with headlights, but I thought that the light was too focused - there were just two really bright white lines going through the picture.  The parking lights only gave a much better effect.  I think that the pattern at the bottom of the light streaks is the builders'' light on the hubcaps, or some part of the wheel.  Not sure how he managed to stand so still for 3.4 seconds...I really thought when I was finished with it that he looked incredibly stiff and unnatural, which is the biggest reason I ended up cropping out his feet.  But no one commented on that, so I guess it must have just been me.</td>', 'Heh.  Well, I think that the white streaks are actually the builders'' light reflecting off the silver car, not the headlights.  I tried it with headlights, but I thought that the light was too focused - there were just two really bright white lines going through the picture.  The parking lights only gave a much better effect.  I think that the pattern at the bottom of the light streaks is the builders'' light on the hubcaps, or some part of the wheel.  Not sure how he managed to stand so still for 3.4 seconds...I really thought when I was finished with it that he looked incredibly stiff and unnatural, which is the biggest reason I ended up cropping out his feet.  But no one commented on that, so I guess it must have just been me.', '2002-06-17 09:24:00.000000', NULL, 0),
(72836, 2372, 327, '<td valign="top">Really liked this shot. Hope your happy with the vote, it did well. The title was GREAT&amp;gt;Nice job.</td>', 'Really liked this shot. Hope your happy with the vote, it did well. The title was GREAT&gt;Nice job.', '2002-06-17 18:36:00.000000', NULL, 0),
(72837, 2373, 1379, '<td valign="top">VERY DANGEROUS!   I like the reflection in your glasses.  Nice!</td>', 'VERY DANGEROUS!   I like the reflection in your glasses.  Nice!', '2002-06-10 10:01:00.000000', NULL, 1),
(72838, 2373, 641, '<td valign="top">great reflections in the glasses.</td>', 'great reflections in the glasses.', '2002-06-10 12:25:00.000000', NULL, 1),
(72839, 2373, 1528, '<td valign="top">original perspective</td>', 'original perspective', '2002-06-10 14:02:00.000000', NULL, 1),
