(72841, 2373, 327, '<td valign="top">Good job and you stayed in your lane too!! Creative idea, clean shot.</td>', 'Good job and you stayed in your lane too!! Creative idea, clean shot.', '2002-06-10 16:57:00.000000', NULL, 1),
