(72846, 2373, 1882, '<td valign="top">hair perfectly in place for the shot.  lol</td>', 'hair perfectly in place for the shot.  lol', '2002-06-11 12:43:00.000000', NULL, 1),
(72847, 2373, 878, '<td valign="top">I find the reflection of the road in the glasses more interesting than the main photo concept.  With that said this is still a clean photo with good exposure and colors.</td>', 'I find the reflection of the road in the glasses more interesting than the main photo concept.  With that said this is still a clean photo with good exposure and colors.', '2002-06-11 17:58:00.000000', NULL, 1),
(72848, 2373, 1005, '<td valign="top">I see, in your glasses.....Good shot, excellent color/focus/etc.  (blank facial expression)  Photo 9 Creativity 6 Road 7 total 7</td>', 'I see, in your glasses.....Good shot, excellent color/focus/etc.  (blank facial expression)  Photo 9 Creativity 6 Road 7 total 7', '2002-06-11 20:57:00.000000', NULL, 1),
